/* Gnamma Stage 84: provisional page-aligned source records; not a certified critical edition. */
window.__GNAMMA_SANANDAJI84.push(...[{"id":"I002.ruled.publisher.01","volume":1,"page":2,"physical_pdf_page":15,"layer":"ruled","title":"Interposed signed editorial explanation of the opening invocations","arabic":"لما كان هذا الكتاب مشتملاً على أهم المطالب الدينية وأعظم المقاصد اليقينية، بدأ رحمه الله بالبسملة اقتداءً بقوله عليه السلام: «كل أمر ذي بال لا يبدأ فيه ...» وإشارة إلى أن مثل هذا الأمر لا يتم إلا بالاستعانة به تعالى وحمده. وهذه البسملة للشارح، وبسملة المصنف هكذا: «بسم الله الرحمن الرحيم وبه نستعين في التتميم». وحذفناها استغناءً عنها. ⟦تلي ذلك جملة مطبوعة غير محرَّرة الضبط هنا، في بيان موضع البسملة في القسم الأول والإشارة إلى أهمية هذا القسم⟧. الفقير إليه فرج الله زكي الكردستاني المرواني الأزهري.","arabic_anchors":"","arabic_status":"continuous_attempt_open_difficult_last_sentences","english":"Because this book embraces the most important religious questions and the weightiest objects of certainty, the commentator—may God have mercy upon him—began with the invocation “In the name of God,” in imitation of the Prophetic saying about every matter of consequence that does not begin with it. He thereby indicates that a task of this kind is accomplished only by seeking God's help and praising Him. This invocation belongs to the commentator. The author of the underlying work begins: “In the name of God, the All-Merciful, the Compassionate; in Him we seek help in completing [the work].” We omitted that invocation because the one already given suffices. [The following printed remarks on where the original author's wording appears, and the significance of the placement, are not secure enough to translate literally from the present scan.] [Signed:] The one in need of Him, Faraj Allāh Zakī al-Kurdistānī al-Marwānī al-Azharī.","reading_status":"new_first_pass_signed_editorial_register_not_complete","source_image":"images/I002.png","stage":81,"attribution":"Signed in print by Faraj Allāh Zakī al-Kurdistānī al-Marwānī al-Azharī","proof_note":"Distinct middle-ruled register on printed I:2. Earlier corpus had only Sanandajī upper invocation and Wasīm lower preface. The final printed prose is partially illegible/uncertain; do not count as full literal page.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":{"source":"Būlāq first-volume page 2","method":"direct image inspection, uncertain endings retained"}},{"id":"I002.upper.01","volume":1,"page":2,"physical_pdf_page":15,"layer":"upper","title":"Sanandajī's invocation","arabic":"بسم الله الرحمن الرحيم. نحمد من هدانا إلى طريق الإسلام، حمداً يوافي نعمه؛ ونشكر الذي وفقنا على تهذيب الكلام وتقريب المرام، شكراً يكافئ مزيده؛ ونصلي صلاة دائمة ما دامت آثار العقائد الإسلامية باقية على صفحات الأيام، على سيدنا ونبينا محمد الذي بعثه إلى كافة الأنام واصطفاه لقمع الضلالة ورفع لواء الهدى، ⟦و... مقام الشفاعة يوم الجزا⟧، وعلى آله البررة الأنقياء.","arabic_anchors":"","arabic_status":"selected_locating_anchors_not_diplomatic","english":"In the name of God, the All-Merciful, the Compassionate. We praise Him who guided us to the path of Islam, with a praise commensurate with His blessings; and thank Him who granted us success in refining theological discourse and bringing its aims within reach, with gratitude answering His increase in bounty. We invoke enduring blessings, for as long as the traces of Islamic belief remain upon the pages of the days, upon our master and Prophet Muḥammad, whom He sent to all humankind and chose to suppress misguidance and raise the banner of guidance, [followed by an ornamentally phrased invocation concerning intercession on the Day of Recompense whose exact wording requires further checking], and upon his noble, pure family. [The invocation continues at I:3.]","reading_status":"continuous_upper_arabic_attempt_open_uncertain_ornate_clause","source_image":"source_images/I002.png","stage":81,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Direct rereading of printed I:2 upper register. One ornate phrase remains bracketed; not a complete diplomatic proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":false,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I002.wasim.01","volume":1,"page":2,"physical_pdf_page":15,"layer":"wasim","title":"Distinct secondary invocation, linked to Wasīm I:3","arabic":"بسم الله الرحمن الرحيم. الحمد لله الذي هدانا لدين الإسلام، ووفقنا على تحرير المقاصد الدينية وتهذيب الكلام، والصلاة والسلام على سيدنا ومقتدانا محمد خير الأنام وآله وعترته","arabic_anchors":"","arabic_status":"selected_locating_anchors_not_diplomatic","english":"In the name of God, the All-Merciful, the Compassionate. Praise belongs to God, who guided us to the religion of Islam and granted us success in elucidating religious aims and refining theological discourse. Blessings and peace upon our master and exemplar Muḥammad, the best of humankind, and upon his family and kin— [continues at I:3].","reading_status":"restored_separate_preface_full_printed_span_first_pass","source_image":"source_images/I002.png","stage":81,"attribution":"positively self-identified authorial preface (retained)","proof_note":"Printed bottom register, self-identified in I:3; matched against earlier source-registered Wasīm preface, not inferred attribution from font or placement.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":false,"provenance":"earlier self-identified Wasim preface translation; this stage only bibliographical attribution audit","source_kind":"locating_arabic_anchors_only"},{"id":"I003.upper.01","volume":1,"page":3,"physical_pdf_page":16,"layer":"upper","title":"Sanandajī explains his undertaking","arabic":"وأصحابه الكرام الأصفياء * وبعد * فيقول العبد الفقير إلى ألطاف ربه الغني * عبد القادر ابن الشيخ محمد سعيد ⟦بقية النسبة غير محررة⟧ * لما كان قسم التهذيب من الكلام * الذي صنفه قدوة الأنام * العلامة الثاني * السعد التفتازاني * ⟦كلام غير منقول هنا⟧ * مع رشاقته ووجازته * مشتملاً على غرر أفكار ⟦…⟧ * إلى أن أشار إليّ من لا يسعني مخالفته * ولا يمكنني إلا موافقته * أن أشرحه شرحاً وافياً ⟦…⟧","arabic_anchors":"«فيقول العبد الفقير إلى ألطاف ربه» · «عبد القادر» · «قسم التهذيب من الكلام» · «العلامة الثاني السعد التفتازاني».","arabic_status":"stage83_bounded_printed_arabic_with_marked_omissions","english":"...and his noble, pure companions. Thereafter, the servant in need of the gracious favours of his Lord, the One free of need—ʿAbd al-Qādir, son of Shaykh Muḥammad Saʿīd [the remainder of the printed designation is not transcribed]—says: The theological division of the Tahdhīb, composed by the renowned scholar Saʿd al-Taftāzānī, despite its elegance and concision, comprises choice ideas [printed intervening language not transcribed here]. Then someone whose request I could not disobey, and with whom I could only agree, indicated that I should give it an ample commentary [the subsequent printed continuation is not yet transcribed].","reading_status":"stage83_bounded_source_translation_not_full_printed_register","source_image":"source_images/I003.png","stage":83,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 83: bounded transcription from original combined-PDF physical p.16 (printed I:3), upper register. First-pass reread of selected printed wording only, no claim of exact full-page or all-register translation. The personal designation, the ornate intervening prose and page-ending are open.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":false,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only","stage81_legacy_english_overview":"Sanandajī identifies himself as ʿAbd al-Qādir, a servant dependent upon God's favour, and describes the kalām section of Taftāzānī's *Tahdhīb* as unusually concise, carefully ordered and rich in subtle points. Although pressed by circumstances, he was urged by a person whose request he could not disregard to explain this difficult text. He therefore undertook a commentary intended to clarify its expressions and recover its intended senses. The sentence continues on I:4.","source_checked_current_turn":true,"source_checker_passes":1,"source_page_verification":"Printed I:3, physical combined PDF p.16"},{"id":"I003.wasim.01","volume":1,"page":3,"physical_pdf_page":16,"layer":"wasim","title":"Wasīm names himself and describes the commentary's origin","arabic":"وكان المحصلون المترددون إلى والدنا الماجد راغبين في تحصيله عنده، ومنهم الأخ الأكبر الماهر الشيخ عبد القادر، وكان في أثناء تحصيله يراجع شرح المقاصد ويأخذ منه معاني دقيقة يكتبها حواشي على هذا المتن المتين بلفظ موجز متين، وبعد إتمام تحصيله جعلها شرحاً له.","arabic_anchors":"«محمد الوسيم ابن المرحوم الشيخ محمد سعيد» · «ومنهم الأخ الأكبر الماهر الشيخ عبد القادر» · «يراجع شرح المقاصد».","arabic_status":"stage83_bounded_printed_arabic_with_marked_omissions","english":"The students who frequented our eminent father were eager to study it with him. Among them was my accomplished elder brother, Shaykh ʿAbd al-Qādir. While studying it, he would consult Sharḥ al-Maqāṣid and take from it subtle meanings, which he wrote as marginal annotations upon this substantial text in concise, precise language. When he had finished his study, he made those notes into a commentary on it.","reading_status":"stage83_bounded_source_translation_not_full_printed_register","source_image":"source_images/I003.png","stage":83,"attribution":"positively self-identified authorial preface (retained)","proof_note":"Stage 83: one contiguous bounded passage reread directly against the lower printed register on I:3 (physical PDF p.16). The preceding and following sentences are still omitted from this unit; this is not the full Wasīm preface.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":false,"provenance":"earlier self-identified Wasim preface translation; this stage only bibliographical attribution audit","source_kind":"locating_arabic_anchors_only","stage81_legacy_english_overview":"In the lower stream, Muḥammad al-Wasīm explicitly names himself. He explains that students studying Taftāzānī with their father included his elder brother ʿAbd al-Qādir. During that study, ʿAbd al-Qādir consulted *Sharḥ al-Maqāṣid*, recording subtle explanations in brief marginal notes; he later made those into a continuous commentary. The shared family and teaching setting explains why the page must preserve **two different narrating voices**.","source_checked_current_turn":true,"source_checker_passes":1,"source_page_verification":"Printed I:3, physical combined PDF p.16"},{"id":"I004.upper.01","volume":1,"page":4,"physical_pdf_page":17,"layer":"upper","title":"Sanandajī's purpose and self-assessment","arabic":"⟦ابتداء الصفحة غير منقول هنا⟧ * خالياً عن شوائب الخلل والنقصان * عالياً أن تطرق إليه قلم النسخ والبطلان * ⟦كلام غير منقول هنا⟧ * وإن رده المتعصبون فسيقبله المنصفون * وإن كنت في ريب من المذكور فانظر ثم ارجع البصر هل ترى من فطور ⟦…⟧","arabic_anchors":"«معانيه وتوضيح عباراته» · «فجاء بحمد الله ذلك شرحاً» · «خالياً عن شوائب الخلل والنقصان» · «فانظر ثم ارجع البصر هل ترى من فطور».","arabic_status":"stage83_bounded_printed_arabic_with_marked_omissions","english":"[The preceding printed description is not transcribed here.] [The author presents the commentary as] free from the admixture of defect and deficiency, beyond the pen of cancellation and annulment. [Intervening words are omitted.] Even if partisans reject it, equitable judges will receive it. If you doubt what has been said, look—and then turn your gaze again: do you see any fissure? [The page-end attribution and verses still require checking.]","reading_status":"stage83_bounded_source_translation_not_full_printed_register","source_image":"source_images/I004.png","stage":83,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 83: bounded printed excerpts from I:4 upper register, physical PDF p.17. The self-praising rhetoric and scriptural allusion are those of the historical author, NOT a modern editorial evaluation. Not a diplomatic transcription of page I:4.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":false,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only","stage81_legacy_english_overview":"The commentary aims to elucidate obscure expressions, clarify intellectual difficulties, and make subtle points accessible. The writer expresses the hope that his labour will be free of significant defects, yet rhetorically invites inspection: ‘Return your gaze: do you see any fissures?’ His praise also acknowledges the teaching of his father and the circumstances that allowed the work to come into being. This is an **authorial rhetorical appeal**, not a modern editorial claim of textual perfection.","source_checked_current_turn":true,"source_checker_passes":1,"source_page_verification":"Printed I:4, physical combined PDF p.17"},{"id":"I004.wasim.01","volume":1,"page":4,"physical_pdf_page":17,"layer":"wasim","title":"Revisions, hardship and relocation","arabic":"⟦افتتاح الصفحة غير منقول هنا⟧ وإني طالما كنت شائقاً إلى أن أكتب على الشرح حواشي تبين مواضعه المشكلة وتحل مسائله المعضلة، لكن ⟦…⟧ فلم تزل الحوادث تتزايد ⟦…⟧","arabic_anchors":"«الشرح مرة ثانية» · «جرح وتعديل» · «أكتب على الشرح حواشي» · «تموجت أمواج المحن والفتن».","arabic_status":"stage83_bounded_printed_arabic_with_marked_omissions","english":"[The beginning of the printed continuation is not transcribed here.] I had long wished to write marginalia upon the commentary, to make clear its difficult passages and resolve its perplexing questions. But ... events went on multiplying [the subsequent narrative, including migration and the family’s circumstances, remains to be transcribed literally].","reading_status":"stage83_bounded_source_translation_not_full_printed_register","source_image":"source_images/I004.png","stage":83,"attribution":"positively self-identified authorial preface (retained)","proof_note":"Stage 83: one bounded sentence of Wasīm’s I:4 autobiographical lower register, with additional locating phrase. No claim of complete lower-page translation; historical narrative retained in legacy summary.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":false,"provenance":"earlier self-identified Wasim preface translation; this stage only bibliographical attribution audit","source_kind":"locating_arabic_anchors_only","stage81_legacy_english_overview":"Wasīm recounts that his elder brother revised the commentary, changing or clarifying some passages. He had long hoped to compose notes on the commentary, to resolve difficult locations and questions. Repeated events delayed him, and disturbances grew until his elder brother left his homeland. Wasīm's account includes the brother's reception in Sulaymāniyya and Wasīm's own grief at separation. It is autobiographical source material; **these historical particulars are not part of Sanandajī's original kalām argument**.","source_checked_current_turn":true,"source_checker_passes":1,"source_page_verification":"Printed I:4, physical combined PDF p.17"},{"id":"I005.upper.01","volume":1,"page":5,"physical_pdf_page":18,"layer":"upper","title":"The title *Taqrīb al-Marām*","arabic":"ولما وفقت بعون الله للإتمام * سميته تقريب المرام * في شرح تهذيب الكلام * أسأل الله أن ينفع به كل ذي ⟦نعت غير متيقن⟧ * بحرمة سيدنا ومقتدانا محمد الهاشمي القرشي * صلى الله عليه وسلم وعلى آله كل غدا وعشي.","arabic_anchors":"«سميته تقريب المرام في شرح تهذيب الكلام» · «محمد الهاشمي القرشي».","arabic_status":"stage83_bounded_printed_arabic_with_marked_omissions","english":"And when, by God’s help, I was enabled to bring it to completion, I called it Taqrīb al-Marām, a commentary on Tahdhīb al-Kalām. I ask God to make it beneficial to every [the printed epithet is not securely read], by the honour of our master and exemplar Muḥammad, the Hāshimī and Qurashī. May God bless him, and his family, morning and evening.","reading_status":"stage83_bounded_source_translation_not_full_printed_register","source_image":"source_images/I005.png","stage":83,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 83: near-continuous source reading of the small upper closing register on I:5 (physical PDF p.18); a rhyming epithet and some orthographic detail still require a second visual proof. The lower Wasīm text on the same page is a different voice.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":false,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only","stage81_legacy_english_overview":"Having composed the commentary, Sanandajī gives it the title *Taqrīb al-Marām fī Sharḥ Tahdhīb al-Kalām*—roughly ‘Bringing the Intended Aim Near: a Commentary on the Refinement of Theological Discourse.’ He closes with a prayer that it benefit its readers and a benediction upon Muḥammad the Hāshimī and Qurashī. The prayer, like the opening, is in rhymed prose.","source_checked_current_turn":true,"source_checker_passes":1,"source_page_verification":"Printed I:5, physical combined PDF p.18"},{"id":"I005.wasim.01","volume":1,"page":5,"physical_pdf_page":18,"layer":"wasim","title":"Wasīm closes his introduction","arabic":"⟦صدر النص غير منقول هنا⟧ وتم الفراغ في سنة ألف ومائتين وثلاثة وسبعين من الهجرة النبوية على صاحبها أزكى التحية.","arabic_anchors":"«سنة ألف ومائتين وثلاثة وسبعين» · «النبوة».","arabic_status":"stage83_bounded_printed_arabic_with_marked_omissions","english":"[The preceding lower-register remarks are not transcribed here.] The completion occurred in 1273 AH, counted from the Prophetic Emigration—upon its bearer be the purest salutations. The exact antecedent of “completion” requires the whole closing statement and should not automatically be treated as the date of the Būlāq printing or of Sanandajī’s entire original commentary.","reading_status":"stage83_bounded_source_translation_not_full_printed_register","source_image":"source_images/I005.png","stage":83,"attribution":"positively self-identified authorial preface (retained)","proof_note":"Stage 83: selected closing date clause in Wasīm’s lower I:5, physical PDF p.18. Its historical referent cannot safely be decided from the extracted clause alone. The source scan must control the date and its surrounding syntax.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":false,"provenance":"earlier self-identified Wasim preface translation; this stage only bibliographical attribution audit","source_kind":"locating_arabic_anchors_only","stage81_legacy_english_overview":"Wasīm's prefatory account concludes with its own reflection on the work's publication, the benefits and difficulties of the commentary, and a stated completion date of **1273 AH**. That date belongs to **his account of completing the prefatory/annotation work**, not automatically to the Būlāq edition or to every portion of the sharḥ. Its exact referent should be established from the entire closing sentence during independent checking.","source_checked_current_turn":true,"source_checker_passes":1,"source_page_verification":"Printed I:5, physical combined PDF p.18"},{"id":"I006.lower.01","volume":1,"page":6,"physical_pdf_page":19,"layer":"lower","title":"Can the chapter plan itself count as the beginning of kalām?","arabic":null,"arabic_anchors":"«(قوله هذا قسم الكلام من التهذيب)» · «غاية تهذيب الكلام» · «في تحرير المنطق وتحرير الكلام» · «ألفاظ ... قسماً من العلم».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal writer examines what is implied by calling this the kalām division of a book which also concerns logic. One might take the wording to mean that the book is ‘refined’ in its entirety; another reading limits the title's effect to the matters explicitly treated under it. The gloss distinguishes a **textual division**, a **field of knowledge**, and the act of **refining a discourse** about that field. The point is relevant because the two sections need not have precisely the same objects, terminology, or demonstrative aim.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I006.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Source-facing marginal reading; not every subordinate example individually translated.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I006.lower.02","volume":1,"page":6,"physical_pdf_page":19,"layer":"lower","title":"Preliminary matters and subject-matter","arabic":null,"arabic_anchors":"«المقدمة» · «الحدّ والموضوع» · «مباحث العلم والنظر» · «التعريف».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal argument also asks which preliminary matters are genuinely needed for the science. A definition of a discipline may address its name, subject, end and benefit; a preliminary discussion may also address the meaning of knowledge and the role of inquiry. Those questions are introduced as **instruments** for the ensuing theological investigation. The writer warns against treating every preliminary logical discussion as though it were already a doctrinal conclusion.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I006.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Connected interpretative lower text, requires literal second pass.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I006.ruled.01","volume":1,"page":6,"physical_pdf_page":19,"layer":"ruled","title":"On the expression ‘section of kalām’","arabic":null,"arabic_anchors":"«(قوله أي ما سيأتي عليك)» · «هذا إشارة من الألفاظ من حيث دلالتها على المعاني» · «(قوله المسمى بالتهذيب)».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On the words “what will come before you,” the commentator points out how the demonstrative is attached to what follows in the written exposition. The title ‘Tahdhīb’ and the expression ‘the division of kalām’ are accordingly explained as designating a **part of a composed text**, not an independently existing scientific object. The gloss also discusses the phrasing and attribution of the title; a short name in the final line is not confidently legible.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I006.png","stage":77,"attribution":"unassigned separately ruled note","proof_note":"Short ruled annotation with an uncertain proper-name reading.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I006.upper.01","volume":1,"page":6,"physical_pdf_page":19,"layer":"upper","title":"The intended portion of the book","arabic":"(هذا) أي ما سيأتي عليك (قسم الكلام من) الكتاب المسمى (بالتهذيب) ⟦بقية الوصلة في التبويب غير منقولة⟧ لأن ما ذكر فيه إما أن يجب تقدمه في علم الكلام وهو الباب الأول في المقدمة أولاً ⟦…⟧","arabic_anchors":"«(هذا) أي ما سيأتي عليك (قسم الكلام من) الكتاب المسمى (بالتهذيب)» · «وقع التبويب» · «المقدمة أولاً».","arabic_status":"stage83_bounded_printed_arabic_with_marked_omissions","english":"“This,” meaning what is about to come before you, “is the kalām division” of the book called al-Tahdhīb. [The intervening description of its chapter arrangement has not yet been copied.] What is discussed in it either needs to precede the investigation of kalām; such material belongs in the first chapter, the introduction [the remaining division is not yet transcribed].","reading_status":"stage83_bounded_source_translation_not_full_printed_register","source_image":"source_images/I006.png","stage":83,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 83: bounded first and third Arabic spans reread from I:6 upper register, physical PDF page 19. The exact intervening classification and separately ruled marginal streams still need transcription.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only","stage81_legacy_english_overview":"“This”—that is, the material about to be presented—is the **division on kalām** in the book called *al-Tahdhīb*. The reason the author has arranged it in chapters is that there are matters which ought to be introduced before the substantive questions of theology. They form the first chapter, a preliminary section; only once those conceptual preliminaries have been set out can the later questions be investigated. The work's division and naming are therefore not arbitrary ornaments but mark the progression of the inquiry.","source_checked_current_turn":true,"source_checker_passes":1,"source_page_verification":"Printed I:6, physical combined PDF p.19"},{"id":"I007.lower.01","volume":1,"page":7,"physical_pdf_page":20,"layer":"lower","title":"What does ‘chapter’ denote?","arabic":null,"arabic_anchors":"«في الباب الأول في المقدمة» · «الظاهر أن الأبواب هي الألفاظ أو النقوش» · «النظر أولاً».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The lower writer observes that a ‘chapter’ can designate the **written headings or sections** of the treatise rather than a metaphysical part of the subject-matter. He is concerned to avoid a purely verbal inference from a heading to a division of reality. The introductory chapter is not the whole of kalām merely because it contains prerequisites of kalām; its function is to explain what the science is and how its arguments proceed.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I007.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Marginal source-facing explanation; some editorial connective phrasing used.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I007.lower.02","volume":1,"page":7,"physical_pdf_page":20,"layer":"lower","title":"What should come before the scientific questions?","arabic":null,"arabic_anchors":"«مباحث العلم والنظر» · «التصور والتصديق» · «المقدمة» · «ما يتوقف عليه الشروع في مسائل العلم».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The gloss asks whether the actual investigation of first principles should precede the definition of the science, or whether the introductory description is sufficient for a reader who has not yet learned the relevant principles. Some knowledge of **conception**, **assent**, and **valid reasoning** is indispensable before proof is possible. But it does not follow that every such preliminary must itself be independently proven at the beginning of the treatise. The author is explaining a pedagogical order, not claiming that the order of printed headings dictates the order of things in the world.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I007.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Provisional connected gloss; word-exhaustive proof pending.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I007.ruled.01","volume":1,"page":7,"physical_pdf_page":20,"layer":"ruled","title":"The beginning of the introduction","arabic":null,"arabic_anchors":"«(الباب الأول في المقدمة)» · «تقدّمه معرفة حدّه وموضوعه وغايته».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"“Chapter One: the Introduction.” Before undertaking the theological proofs, the reader is given an account of the science's **definition**, **subject**, and **aim**. These preparatory notions make the manner in which the subsequent problems are investigated intelligible.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I007.png","stage":77,"attribution":"unassigned separately ruled note","proof_note":"Title and middle short printed line; not a named authorial note.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I007.upper.01","volume":1,"page":7,"physical_pdf_page":20,"layer":"upper","title":"Sequence of the later chapters","arabic":"⟦ابتداء الوصلة من الصفحة السابقة غير منقول هنا⟧ وهو الباب الثاني في الأمور العامة، أو ما يختص بالممكن الذي لا يقوم بنفسه بل بغيره وهو الباب الثالث في الأعراض، أو بالممكن الذي يقوم بنفسه وهو الباب الرابع في الجواهر، وأما الواجب تعالى فإما باعتبار إرساله الرسل وبعثه الأنبياء وهو الباب السادس في السمعيات، أو لا باعتباره وهو الباب الخامس في الإلهيات. الباب الأول في المقدمة.","arabic_anchors":"«الثلاثة في الوجود وهو الباب الثاني في الأمور العامة» · «الثالث في الأعراض» · «الرابع في الجواهر» · «الخامس ... بالواجب تعالى» · «السادس في السمعيات ... الباب الخامس في الإلهيات».","arabic_status":"stage83_bounded_printed_arabic_with_marked_omissions","english":"[The opening link from the preceding page is not yet transcribed.] That is the second chapter, concerning general matters. Or the topic may concern what is possible and does not subsist in itself but in another: the third chapter, on accidents. Or it may concern what is possible and subsists in itself: the fourth chapter, on substances. As for the Exalted Necessary One, either He is treated with regard to sending messengers and raising up prophets—this is the sixth chapter, on matters known by transmission—or without that consideration: the fifth chapter, on divine matters. Chapter One: the Introduction.","reading_status":"stage83_bounded_source_translation_not_full_printed_register","source_image":"source_images/I007.png","stage":83,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 83: a sustained transcription of the upper register on I:7, physical PDF p.20, excluding the uncertain initial connection. The page also has separately ruled and lower registers, neither fully proofed. The apparently nonsequential mention of sixth before fifth follows the printed argument and must not be silently reordered.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only","stage81_legacy_english_overview":"After the preliminary chapter, the subject is arranged in a progression: the **general matters of being**; matters concerning **accidents**; matters concerning **substances**; the **Necessary Existent**, or what pertains to God; and finally the **things known by transmission**, where the revealed reports and the mission of the Messenger are treated. The chapter headings have their own technical ordering, and the commentator explains how the labels for the wider theological divisions correspond to the actual sequence within the *Tahdhīb*.","source_checked_current_turn":true,"source_checker_passes":1,"source_page_verification":"Printed I:7, physical combined PDF p.20"},{"id":"I008.lower.01","volume":1,"page":8,"physical_pdf_page":21,"layer":"lower","title":"Why distinguishing kalām by ‘belief’ is difficult","arabic":"قوله خاصة والمراد من اختصاص علم الكلام هو الاختصاص الإضافي على ما صرح به المصنف في شرح المقاصد","arabic_anchors":"«(قوله خاصة)» · «الاختصاص بعلم الكلام» · «الاختصاص ... على ما صرح به المصنف في شرح المقاصد» · «اعتقاد القلب».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"Concerning his expression “specifically”: the particularity intended for the science of kalām is a relative particularity, as the author explicitly states in Sharḥ al-Maqāṣid.","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I008.png","stage":84,"attribution":"unassigned lower printed commentary","proof_note":"Stage 84 visually reread from printed page I:8; Only the initial marginal argument is transcribed; its continuation and the second lower block are substantial. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 21. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"The marginal commentator insists that the difference between kalām and logic or law cannot simply be a difference in **subject terms**. Many theological proofs concern bodies, accidents, possibility, causality and language, all of which can also be examined in other disciplines. The relevant differentiation is through the **end for which the inquiry is undertaken**: establishing a religious belief rather than, for instance, deriving a legal action or analysing the formal structure of an inference.","stage84_source_review":true},{"id":"I008.lower.02","volume":1,"page":8,"physical_pdf_page":21,"layer":"lower","title":"Necessary judgments and practical judgments","arabic":null,"arabic_anchors":"«الأحكام التي يتعلق الغرض بمجرد اعتقادها» · «وجوب القلب» · «الأحكام الشرعية» · «كيفية العمل».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Some religious judgments call for the **assent** of the believer; others are concerned with the manner of acting. The marginal writer examines whether this separation is absolute or is better expressed by a difference in the **proximate aim** of the relevant science. An obligatory practical act may also be something one must believe is obligatory; that does not make its detailed derivation a question of kalām. Likewise, a proposition about theological doctrine may have practical consequences without ceasing to be a doctrinal proposition.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I008.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Connected lower reading, several compact examples unverified.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I008.ruled.01","volume":1,"page":8,"physical_pdf_page":21,"layer":"ruled","title":"Remarks on the naming of the discipline","arabic":"(قال المصنف رحمه الله الكلام هو العلم إلخ) أي علم الكلام هو","arabic_anchors":"«(قال المصنف رحمه الله الكلام هو العلم الخ)» · «أي علم الكلام».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"“The author—may God have mercy on him—said: ‘Kalām is knowledge,’ etc.” That is, the science of kalām is [the knowledge here intended].","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I008.png","stage":84,"attribution":"unassigned separately ruled note","proof_note":"Stage 84 visually reread from printed page I:8; The ruled author’s historical theories of the name kalām remain untranscribed, and no author is inferred for this note. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 21. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"On the author's words “kalām is knowledge, etc.”: the phrase is intended as **‘the science of kalām’**, not a statement that every instance of speech counts as knowledge. The gloss alludes to other historical explanations of why the discipline came to be called ‘kalām’; these alternatives do not all supply its formal definition.","stage84_source_review":true},{"id":"I008.upper.01","volume":1,"page":8,"physical_pdf_page":21,"layer":"upper","title":"The specific scope of theological science","arabic":"كمباحث العلم والنظر والدليل لأن تحصيل العقائد بطريق النظر والاستدلال والرد على منكري حصول العلم مطلقا أو استفادته من النظر مطلقا أو في الإلهيات خاصة يتوقف على ذلك","arabic_anchors":"«الكلام خاصة» · «كمباحث العلم والنظر والدليل» · «لا تحصل العقائد بطريق النظر والاستدلال» · «الإلهيات خاصة».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"[These introductory investigations include] questions of knowledge, inquiry and proof, since acquiring doctrines through reflection and inference—and responding to those who deny the attainment of knowledge altogether, or deny that it is gained through reflection either in general or specifically in divine matters—depends upon them.","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I008.png","stage":84,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 84 visually reread from printed page I:8; Upper opening follows the I:7 division; the brief concluding transition on I:8 is not transcribed. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 21. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"The designation ‘kalām’ does not simply mean every investigation of **knowledge, inquiry, and evidence**. Those subjects also belong to logic and the theory of demonstration. Nor is its defining mark merely that doctrinal propositions are asserted. What distinguishes this science is the way its investigations are ordered toward establishing **religious convictions** through arguments. The statement therefore moves from the preparatory discussion to a definition of kalām.","stage84_source_review":true},{"id":"I008.upper.02","volume":1,"page":8,"physical_pdf_page":21,"layer":"upper","title":"Definition through doctrinal knowledge","arabic":"(الكلام هو العلم بالعقائد) وهي الأحكام التي يتعلق الغرض بمجرد اعتقادها بالقلب","arabic_anchors":"«(الكلام هو العلم بالعقائد)» · «وهي الأحكام التي يتعلق الغرض بمجرد اعتقادها بالقلب».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"“Kalām is knowledge of doctrines”: these are judgments whose intended object is simply their being believed in the heart.","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I008.png","stage":84,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 84 visually reread from printed page I:8; Only the opening lemma and its immediate explanation are transcribed; the upper discussion continues and the different practical class is not fully entered. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 21. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"“Kalām is knowledge of the doctrines.” These are judgments for which the relevant end is **assent in the heart** as such, rather than the bodily execution of a practice. This distinction does not imply that religious practice is unimportant; rather, it determines the formal respect under which the science studies its judgments, in contrast to a discipline concerned with the practical derivation of rulings.","stage84_source_review":true},{"id":"I009.lower.01","volume":1,"page":9,"physical_pdf_page":22,"layer":"lower","title":"Why the distinction does not reduce kalām to fiqh","arabic":null,"arabic_anchors":"«الفقه ذكرنا لا إجماع حيث يتعلق الغرض باعتقادها دون العمل بها» · «تدخل في التعريف» · «في أصول الفقه مقصودة لذاتها».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal discussion distinguishes an act's being relevant to *belief about a ruling* from the act's *practical observance*. Some propositions examined in law or legal theory can enter theology under a different respect, namely when what matters is assent to a revealed judgment rather than deriving an action from it. That change of perspective does not turn kalām into jurisprudence: in legal theory, the principles are pursued for their role in establishing rulings; in kalām, a proposition can be discussed because of its relation to religious belief itself. The writer tests which disciplines would be improperly included if this regard were omitted from the definition.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I009.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Lower-register source-facing explanation, several lines compressed in English.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I009.lower.02","volume":1,"page":9,"physical_pdf_page":22,"layer":"lower","title":"The imitator, fallible assent and status of evidence","arabic":null,"arabic_anchors":"«(قوله عن الأدلة اليقينية)» · «(قوله سواء طابق الواقع أو لا)» · «(قوله أي المكتسب)».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On the phrase “from certain proofs,” the gloss presses the distinction between possession of a true belief and possession of it **through an argument**. The imitator may assent to a true theological proposition without himself knowing the proof. If every correct conviction were counted as the science of kalām, its boundary would expand beyond the intellectual activity under definition. Conversely, treating any proof the speaker calls “certain” as genuinely demonstrative risks admitting erroneous arguments. The author of the gloss does not allow the subjective impression of certainty to settle this issue.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I009.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Argument summary grounded in visible anchors; literal clause mapping incomplete.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I009.ruled.01","volume":1,"page":9,"physical_pdf_page":22,"layer":"ruled","title":"The intended scope of ‘acquired’","arabic":"(قوله أي المكتسب) أشار بهذا التفسير رحمه الله إلى أن قوله عن الأدلة متعلق بالعلم باعتبار تضمنه معنى الاكتساب","arabic_anchors":"«(قوله أي المكتسب)» · «الدليل متعلق بالعلم» · «باعتبار تضمّنه معنى الاكتساب لا ...» · «الإذعان في المقاصد».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"Concerning his words “that is, acquired”: by this explanation—may God have mercy upon him—he indicates that “from proofs” is connected with “knowledge,” insofar as it involves the notion of acquisition.","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I009.png","stage":84,"attribution":"unassigned separately ruled note","proof_note":"Stage 84 visually reread from printed page I:9; Initial ruled grammatical gloss only; remaining printed clause is open. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 22. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"On “that is, acquired”: the phrase about proofs is understood as relating to knowledge **insofar as it is acquired**, rather than as an independent condition attached indiscriminately to every belief. This is a grammatical and conceptual clarification: it explains why the definition appeals to proofs where the activity of the discipline is demonstrative, without implying that every occurrence of the same theological proposition must be acquired by a proof.","stage84_source_review":true},{"id":"I009.upper.01","volume":1,"page":9,"physical_pdf_page":22,"layer":"upper","title":"Religious convictions rather than juridical practice","arabic":"(الدينية) المنسوبة إلى دين نبينا محمد صلى الله عليه وعلى آله وسلم ⟦كلام مطبوع متروك هنا⟧ وسواء كانت من الدين في الواقع ككلام أهل الحق أم لا ككلام الفرق المبتدعة الضالة","arabic_anchors":"«الاعتقاد، أيضاً المقصود من العلم به علم الفقه» · «(الدينية) المنسوبة إلى دين نبينا محمد صلى الله عليه وعلى آله وسلم» · «سواء أكانت من الدين في الواقع ككلام أهل الحق أم لا ككلام الفرق المبتدعة».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"“Religious”: ascribed to the religion of our Prophet Muḥammad—may God bless him and his family and grant him peace. [An intervening printed qualification has not been transcribed.] Whether they belong to the religion in reality, as in the discourse of those the writer calls the people of truth, or do not, as in the discourse of groups he calls errant innovators.","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I009.png","stage":84,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 84 visually reread from printed page I:9; Explicit middle omission; the attribution belongs to the historical discourse, not a modern editorial endorsement. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 22. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"What is at issue is **doctrinal assent**, not the objects of jurisprudential knowledge in their practical aspect. “Religious” means attributed to the religion of our Prophet Muḥammad—God bless him and his family and grant him peace. The designation can therefore include both propositions that truly belong to that religion, as the author understands the discourse of the orthodox, and propositions that are only **claimed** to belong to it, as in the discourse of groups he calls innovators. Such attribution does not imply that every proposition so named is correct. The author is defining the class of questions discussed in a discipline, not certifying every proposed answer.","stage84_source_review":true},{"id":"I009.upper.02","volume":1,"page":9,"physical_pdf_page":22,"layer":"upper","title":"Evidence that yields certainty","arabic":"(عن الأدلة اليقينية) أي المكتسب","arabic_anchors":"«فإذا كان المراد من العلم مطلق التصديق سواء طابق الواقع أو لا ...» · «(عن الأدلة اليقينية) أي المكتسب».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"“From certain proofs”—that is, [knowledge] acquired [through those proofs].","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I009.png","stage":84,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 84 visually reread from printed page I:9; The prior objection about mistaken assent and its final qualification are not fully transcribed; I:10 continues the argument. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 22. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"If “knowledge” is interpreted indiscriminately as any assent, whether or not it corresponds to reality, the definition would also include mistaken conviction. The qualification “from **certain proofs**” is introduced to delimit the intended sort of acquired cognition. But it raises a further question: does certainty here qualify the *proof objectively*, the *knower's state*, or the *evidence as deemed certain by the proponent*? The next page examines these readings rather than presuming their equivalence.","stage84_source_review":true},{"id":"I010.lower.01","volume":1,"page":10,"physical_pdf_page":23,"layer":"lower","title":"Error, opinion and objective conformity","arabic":null,"arabic_anchors":"«(قوله العلم اليقيني)» · «المطابق للواقع في نفس الأمر» · «(قوله الدليل اليقيني)» · «لا يخرج إدراك المخطئ».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “certain knowledge,” the gloss asks whether *conformity to reality* is built into the notion of knowledge. If it is, a wrong judgment cannot become knowledge merely through its firmness. If the proof is “certain” only **in the disputant's opinion**, incorrect judgments may again enter through that concession. A likely intended response distinguishes correctness from the psychological condition of firmness; both must be checked. The marginal writer is investigating the **scope of the definition**, not asserting that all reported opinions have the same evidential standing.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I010.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Partial lower translation, no definitive transcription.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I010.lower.02","volume":1,"page":10,"physical_pdf_page":23,"layer":"lower","title":"The difficult case of the imitator","arabic":null,"arabic_anchors":"«(قوله العقيدة بزعم المستدل)» · «المطابقة للواقع باعتقاده» · «التصديق الجازم سواء طابق الواقع أم لا» · «المقلد».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"A person who imitates a teacher can hold a firm conviction and even, by good fortune, a true one; but that alone does not mean he possesses the **science** characterised by justified inference. The gloss tests whether the exclusion is achieved by “certain” or only by specifying the act of acquisition from proofs. It also distinguishes an opinion which is merely *probable*, a categorical **error**, and a firmly held **true** assertion. None should be conflated with the activity of establishing religious doctrines through arguments.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I010.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Source-facing marginal account; lower proof remains open.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I010.lower.03","volume":1,"page":10,"physical_pdf_page":23,"layer":"lower","title":"Does kalām concern only necessary propositions?","arabic":null,"arabic_anchors":"«اليقين ...» · «هل المراد ... القطعية» · «علم الكلام».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The discussion notes that a proof of a theological claim must not be judged conclusive merely because its proponent feels no doubt. Nor does the word *certainty* mean that every theological issue is a self-evident proposition. It concerns the character of the assent appropriately established by the investigation. The closing observation returns to the stated limits of the discipline and supplies the join to I:11.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I010.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Condensed lower text; final compact sentences still need separate Arabic extraction.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I010.upper.01","volume":1,"page":10,"physical_pdf_page":23,"layer":"upper","title":"Is certainty in the proof or in the mind?","arabic":"لأن الدليل اليقيني ما يفيد اليقين إلا أنهم قالوا المراد بالأدلة اليقينية المعتقدة بزعم المستدل","arabic_anchors":"«ذلك العلم عن أدلتها» · «العلم اليقيني» · «لأن الدليل اليقيني ما يفيد اليقين» · «المراد بالأدلة العقدية المعتقدة بزعم المستدل».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"For a certain proof is one that produces certainty. Yet they said that what is meant by “certain proofs” is proofs believed [to be certain] in the judgment of the one arguing.","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I010.png","stage":84,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 84 visually reread from printed page I:10; The upper response before and after this sentence is not fully transcribed; “believed” is not to be mistaken for objective certitude. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 23. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"The qualification directs one to knowledge **through its proofs**, and the evidence called certain is, strictly speaking, that which gives rise to certainty. Yet a different reading is also reported: the proofs intended might be those **believed to be conclusive by the person arguing**. These are not equivalent. In one reading the definition selects genuinely warranted cognition; in the other it describes the kind of claim put forward by practitioners, including those who dispute one another.","stage84_source_review":true},{"id":"I010.upper.02","volume":1,"page":10,"physical_pdf_page":23,"layer":"upper","title":"The boundaries of acquired religious knowledge","arabic":null,"arabic_anchors":"«ثم إنهم اعتبروا في أدلتها اليقين» · «لئلا عبرة بالظن في الاعتقادات» · «وعلم الرسول بالاعتقادات وكذا اعتقاد المقلد».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Because these are questions of faith, some authors demand certainty rather than mere probability. But the commentary asks about exceptional forms of correct theological assent: God's knowledge, prophetic knowledge, and the conviction of a person who merely follows another. The function of the word “science” in the definition must be **acquired and disciplined doctrinal knowledge**, not the simple occurrence of a true judgment in any knower whatever. The argument is continued on I:11.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I010.png","stage":77,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Upper text, joined I:10→11.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I011.lower.01","volume":1,"page":11,"physical_pdf_page":24,"layer":"lower","title":"Whether imitation can count as justified knowledge","arabic":null,"arabic_anchors":"«(قوله وكذا اعتقاد المقلد)» · «أهل الكشف» · «المعتقد المقلد» · «الاعتقاد الجازم».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The lower author tests the previous claim about imitation. An imitator's conviction may be firmly held and correspond to reality, yet lack the evidence appropriate to a demonstrative science. In contrast, the settled cognition of a competent investigator may be acquired through the orderly pursuit of proof. The gloss distinguishes the issue **whether a belief is true** from the issue **whether its possessor can establish it**. That distinction bears directly on the definition of kalām by proofs.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I011.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Lower argument partly interpretative.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I011.lower.02","volume":1,"page":11,"physical_pdf_page":24,"layer":"lower","title":"Is ‘the known’ too broad a subject?","arabic":null,"arabic_anchors":"«(قوله موضوعه)» · «لفظ المعلوم» · «الموضوع عام» · «العقائد الدينية».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The subject term “the known” appears excessively broad, since it can include both what exists and what does not, and things studied by many other sciences. The commentator therefore insists on the delimiting **relation to religious doctrines**. Another question arises: does the word “known” refer to the *subject term* in every theorem, to all entities in the field, or to whatever is considered for the sake of proving theological conclusions? An adequate definition must not switch silently between these senses.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I011.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Marginal source-facing reading; line-by-line correspondence pending.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I011.lower.03","volume":1,"page":11,"physical_pdf_page":24,"layer":"lower","title":"Propositions versus constituent terms","arabic":null,"arabic_anchors":"«التصديق بوجود الموضوع» · «جزء من المعلوم» · «المبادئ التصورية» · «المبادئ التصديقية».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The margin elaborates the relation between knowing the *terms* of a proposition and assenting to the *proposition itself*. Demonstration presupposes conceptions of its terms, while the truth of a conclusion involves judgment. On that basis, subjects, predicates and first principles may all enter a discipline without each separately being the final object of its assent. This is relevant to whether the subject of kalām should be stated in terms of “the known” or in terms of the propositions it establishes.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I011.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Provisional lower explanation, ending connects to I:12.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I011.upper.01","volume":1,"page":11,"physical_pdf_page":24,"layer":"upper","title":"The Companions and the historical term ‘kalām’","arabic":"علم الصحابة وإن لم يسم في ذلك الزمان بالكلام كما أن علمهم بالعمليات فقه وإن لم يسم به","arabic_anchors":"«علم الصحابة» · «وإن لم يسمَّ في ذلك الزمان بالكلام» · «كما أن علمهم بالحساب ... لم يسمَّ به».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"[The doctrinal] knowledge of the Companions [was present] even if it was not called kalām in that age, just as their knowledge of practical matters was jurisprudence even if it was not called by that name.","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I011.png","stage":84,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 84 visually reread from printed page I:11; A sentence continuing from I:10; initial words depend on the preceding page. Note بالعمليات, not بالعقائد, in the second comparison. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 24. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"The knowledge possessed by the Prophet's Companions was not called “kalām” at the time, just as their knowledge of other matters was not necessarily named after the later disciplines in which those matters were organised. The historical **name** of a discipline does not determine whether earlier persons possessed the relevant knowledge. One must distinguish the activity or insight from the subsequent technical label applied to it.","stage84_source_review":true},{"id":"I011.upper.02","volume":1,"page":11,"physical_pdf_page":24,"layer":"upper","title":"Subject of the science","arabic":"(وموضوعه المعلوم من حيث يتعلق بذلك)","arabic_anchors":"«(وموضوعه المعلوم من حيث يتعلق بذلك)».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"“Its subject is the knowable insofar as it bears upon that [doctrinal concern].”","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I011.png","stage":84,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 84 visually reread from printed page I:11; Only the short parenthesized lemma is entered; the following explanation continues on I:12. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 24. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"“Its subject is **the known**, insofar as it is connected with that”—that is, with the establishment of religious doctrines. The restriction “insofar as” is doing essential work: kalām is not simply an inventory of all knowable things, but a study of things under the regard in which they enter demonstrations concerning belief.","stage84_source_review":true},{"id":"I012.lower.01","volume":1,"page":12,"physical_pdf_page":25,"layer":"lower","title":"The author's use of ‘connection’","arabic":null,"arabic_anchors":"«(قوله أي بالعقائد الدينية الخ)» · «الأحكام والنسب» · «لا يتم بيان الموضوع بدون غير الموضوع».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The lower commentary objects that the phrase “insofar as it is connected with religious doctrines” requires explanation. The proof of a theological assertion may use not only doctrines but **relations, negations, and judgments** concerning items considered in other disciplines. Some things are not taken up because of their intrinsic nature, but because denying or affirming them makes a difference to an eventual conclusion. The author tests whether that consideration is sufficient to distinguish kalām from other sciences, or merely imports their questions wholesale.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I012.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Connected lower source interpretation; incomplete literal transcript.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I012.lower.02","volume":1,"page":12,"physical_pdf_page":25,"layer":"lower","title":"Predicates and the relation of the ‘known’","arabic":null,"arabic_anchors":"«(قوله المتناول للموجود والمعدوم)» · «المعلوم» · «الموضوع» · «المحمول».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The breadth of the known object matters especially when a question concerns a thing **that cannot exist**. The impossible is still an object of conceptual judgment: one can affirm its impossibility without giving it external existence. The gloss turns from this to a logical objection. If the theological matter is **predicated** of a subject rather than itself functioning as the subject term, can the definition still say “the known” is the science's subject? The discussion prepares the solution on I:13, where the predicates of theological problems are explicitly mentioned.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I012.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Source-facing partial translation of the long lower continuation; the opening should be checked together with I:11.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I012.ruled.01","volume":1,"page":12,"physical_pdf_page":25,"layer":"ruled","title":"Does a subject have to be demonstrable in every proposition?","arabic":null,"arabic_anchors":"«(قوله لا تبحث الخ)» · «بموضوعية الموضوع» · «اه منه».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal note tests the claim that inquiry must always be about the subject *as such*. It is enough in some cases to understand how the subject or a property of the subject figures in a chain of demonstration. The distinction is again a matter of how propositions are organised within the science, not a proof that the things considered are all actual existents.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I012.png","stage":77,"attribution":"unassigned separately ruled note","proof_note":"Middle ruled note, partial reading. A compact clause requires another image check.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I012.upper.01","volume":1,"page":12,"physical_pdf_page":25,"layer":"upper","title":"The range of auxiliary questions","arabic":"أي بالعقائد الدينية لأنه يبحث فيه عن أحوال الصانع من القدم والوحدة وغيرهما وعن أحوال الجسم والعرض والحدوث والتركيب من الجواهر الفردة وقبول الفناء وغير ذلك","arabic_anchors":"«أي بالعقائد الدينية» · «أحوال المانع من القدم والوحدة» · «أحوال الجسم والعرض والحدوث والتركيب» · «أحوال المحال والمعدومات».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"That is, in relation to religious doctrines; for it investigates the states or attributes of the Maker, including beginninglessness and oneness, and also questions of body and accident, origination, composition from indivisible particles, susceptibility to annihilation, and other matters.","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I012.png","stage":84,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 84 visually reread from printed page I:12; Selected contiguous opening of I:12; remainder of examples and terminological question still require complete transcription. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 25. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"The connection intended is to **religious doctrines**. The scope of inquiry therefore includes characteristics that exclude a body's beginninglessness or absolute unity, the properties of body and accident, origination and composition, and questions about substantiality, individuation and other categories. It also extends to **impossibilities** and **nonexistents**, so far as propositions about them are needed to establish the desired doctrines. The scope is not limited to propositions that themselves state an article of faith; the inquiry can examine premises and distinctions used to demonstrate such propositions.","stage84_source_review":true},{"id":"I012.upper.02","volume":1,"page":12,"physical_pdf_page":25,"layer":"upper","title":"A common subject broad enough for nonexistents","arabic":"فالمراد بموضوعات هذه المسائل هو المعلوم المتناول للوجود والعدم وقد يقال المعلوم","arabic_anchors":"«فالمعلوم المتناول للموجود والمعدوم» · «وقد قيل المعلوم».","arabic_status":"stage84_bounded_printed_excerpt_untranscribed_printed_continuation","english":"Thus what is intended as the subject of these investigations is the knowable, comprising existence and nonexistence. One may also say: the knowable ... [the following qualification has not been entered].","reading_status":"stage84_source_image_read_bounded_not_all_register_not_final","source_image":"source_images/I012.png","stage":84,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Stage 84 visually reread from printed page I:12; Opening phrase of the second upper argument only; must be joined to complete explanation of the science’s subject and include its ruled/lower glosses. Untranscribed parts remain visible in facsimile. No independent secondary proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"Stage 84 direct reread of Būlāq 1318 AH printed source image, source physical PDF page 25. Previous Stage 83 overview retained separately as historical commentary.","source_kind":"locating_arabic_anchors_only","stage83_historical_english_overview":"Consequently the “known” can be taken broadly enough to embrace **existent and nonexistent** alike. This is why the discipline's subject cannot simply be “body,” “existent substance,” or another restricted ontological genus. Whatever is needed as a subject of intellectual judgment under the specified theological relation can enter consideration.","stage84_source_review":true},{"id":"I013.lower.01","volume":1,"page":13,"physical_pdf_page":26,"layer":"lower","title":"Is the 'known' an adequate general subject?","arabic":null,"arabic_anchors":"«من الذهني وغيره يساوي الموجود المعدوم في العموم» · «إنما يحتاج إليه عند من يجعل مباحث المعدوم والمحال من مسائل علم الكلام» · «أن المراد بالعقائد الدينية المحمولات».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal writer begins by challenging how the ‘known’ is supposed to extend to what exists only in thought as well as to what exists outside thought. Making the known object of inquiry fully coextensive with existence and nonexistence may be broader than the argument warrants. The issue becomes pressing especially if one counts discussion of the nonexistent and the impossible among the questions of kalām. The writer therefore asks whether the alleged subject is being construed as the *subject term* of the propositions, their *predicates*, or the whole range of things to which theological demonstration must refer. He reports the suggestion that ‘religious doctrines’ denotes the predicates, but cautions that this may not settle the problem by itself.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I013.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Lower-gloss source-facing exposition, not a complete literal rendering of every line.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I013.lower.02","volume":1,"page":13,"physical_pdf_page":26,"layer":"lower","title":"Indirect propositions and intermediate bases","arabic":null,"arabic_anchors":"«من حيثية التعلق بالمحمول كما يتناول الموضوع» · «ليس هذا الإخراج من ورطة» · «قال المصنف» · «ليس تصوراً لموضوعه».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The text develops a difficulty in restricting the discipline to its directly professed conclusions. It is not enough simply to say that what enters a proof as a premise is itself a credal conclusion: a science often studies conditions of its own arguments without taking each such condition as its final object. A predicate may be introduced under the respect in which it relates to an ultimate doctrinal result, just as a subject can be. The commentator uses this to question whether the proposed escape from the difficulty is genuine, rather than a shift between two ways of describing the same material.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I013.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Connected argumentative paraphrase; several compact expressions at the top of the lower stream remain uncertain.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I013.lower.03","volume":1,"page":13,"physical_pdf_page":26,"layer":"lower","title":"‘Ultimate’ and ‘proximate’ ends of the discipline","arabic":null,"arabic_anchors":"«(قوله الفوز بسعادة الدارين)» · «ذكروا أن الفائدة والغاية والمنفعة أمور لا تختلف إلا بالحيثية والاعتبار» · «بالأحكام الشرعية اعتقاداً حقاً» · «لا يؤدي إلى الفساد في الآخرة».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “attaining felicity in the two abodes”: benefit, end, and utility are not always three distinct realities; they may describe one result under different **considerations**. The nearer end of kalām is to establish firmly and correctly the doctrines that belong to religion, removing uncertainty and error. Its more remote end is a right faith that prevents misdirection in this life and leads toward deliverance in the next. The marginal writer objects to confusing this final good with the particular cognitive act that defines the science; something may be sought through the science without thereby becoming the science's own formal subject.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I013.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Lower text partly normalized in English; the precise wording of the final lines joins I:14.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I013.ruled.01","volume":1,"page":13,"physical_pdf_page":26,"layer":"ruled","title":"Sufficiency of the subject-based distinction","arabic":null,"arabic_anchors":"«المعلوم المذكور لا يعتبر من المحمول» · «المقصود من ذلك تمييز العلم من سائر العلوم باعتبار الموضوع» · «والبيان المذكور كاف فيه» · «اه منه».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The ‘known’ that was mentioned is not itself treated here as one of the predicates. The purpose is to distinguish this science from other sciences **by reference to its subject**, and the explanation given is sufficient for that. Allowing the discussion also to range over predicates does not destroy the proposed distinction. [The closing «منه» denotes a source or speaker, but does not independently identify a named glossator.]","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I013.png","stage":77,"attribution":"unassigned separately ruled note","proof_note":"Separately ruled text; source-located reading.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I013.upper.01","volume":1,"page":13,"physical_pdf_page":26,"layer":"upper","title":"Predicates of theological questions","arabic":null,"arabic_anchors":"«من الحيثية المذكورة يتناول محمولات مسائله» · «العقائد الدينية» · «المحمولات ...» · «فلا إشكال».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Under the respect already specified, the expression also embraces the **predicates** in the propositions that constitute its questions. One may therefore say that the religious doctrines intended here are the things predicated within the discipline, and what serves as the means of reaching those doctrines. On that understanding, the objection—that not every matter investigated is itself one of the credal conclusions—does not arise. [The precise intervening formulation after *al-maḥmūlāt* is difficult in this impression; the paraphrase is explicitly provisional.]","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I013.png","stage":77,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Source-facing, interpretative at one indistinct phrase; no independent second proof.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I013.upper.02","volume":1,"page":13,"physical_pdf_page":26,"layer":"upper","title":"Benefit and ultimate end","arabic":null,"arabic_anchors":"«وفائدته أمور وغاية الكل الفوز بسعادة الدارين» · «وكان المصنف يرى أنه من العلوم التي غايتها أنفسها فاكتفى ببيان ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The discipline has several benefits, while their ultimate end is **attaining felicity in the two abodes**. The commentator suggests that the author regarded this as one of the sciences whose immediate aim is, in one respect, its own knowledge. That helps explain why he was satisfied with specifying the discipline itself rather than treating every benefit or remoter aim as its defining subject.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I013.png","stage":77,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Connected upper-text reading; final word of the last clause requires a high-resolution recheck.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I014.lower.01","volume":1,"page":14,"physical_pdf_page":27,"layer":"lower","title":"The two possible senses of an end","arabic":null,"arabic_anchors":"«العلم غاية لنفسه» · «لا تكون غاية الغاية» · «أن الأمور التي غايتها الفوز لا الفوز نفسه».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal writer asks what the earlier reference to the end intends. If knowing itself is the immediate aim, a further end such as felicity can only be called the ‘end of the end’ under a particular ordering of aims. Not every benefit produced by a discipline is part of its essence or immediate purpose. The criticism is directed against sliding between the **knowledge sought**, the **good achieved through possessing it**, and the **farther religious outcome** of such possession.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I014.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Lower-register source-based reading, selected clauses; not all words diplomatically transcribed.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I014.lower.02","volume":1,"page":14,"physical_pdf_page":27,"layer":"lower","title":"Does knowledge of one's existence require prior knowledge of knowledge?","arabic":null,"arabic_anchors":"«تصور العلم بديهي» · «لوجهين الأول أنه معلوم» · «اكتساب الماهوية» · «فحكم الوجدان» · «إما ضرورة ... أو اكتساب».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The margin distinguishes knowing that one exists from possessing a definition of what ‘knowledge’ means. One may immediately have a cognition without being able to analyse its nature. The fact that something is given in awareness is not in itself a proof that its **quiddity**, as an object of reflective analysis, is also immediately apprehended. If one says that the conception of knowledge is acquired, a question remains: what knowledge must be present for the acquisition to take place? The argument is delicate because it can use *knowledge* for the act of apprehension in one premise and for the concept being studied in another.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I014.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Partly interpretative lower reading; this distinction is explicit in the print, but the full argument is lengthy.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I014.lower.03","volume":1,"page":14,"physical_pdf_page":27,"layer":"lower","title":"Circularity, ‘beginning’ and the limits of the proof","arabic":null,"arabic_anchors":"«يلزم الدور» · «بداهته مستلزمة لعدم تجدد» · «مستلزم للمطلوب المذكور» · «معلوم لا بالضرورة بل بالاكتساب».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The critic tests the regress argument by distinguishing an unqualified prior act of knowing from a reflexive act in which knowledge becomes its own object. If every act of knowing presupposed a previously **defined** notion of knowledge, a circle would indeed appear; but if an initial act can occur without reflective grasp of its nature, the inference requires another premise. Conversely, declaring that all cognition must be obtained through acquisition raises the question of its beginning. The marginal discussion does not treat these alternatives as automatically equivalent.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I014.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Close source-guided synthesis. The sentence continues onto I:15.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I014.upper.01","volume":1,"page":14,"physical_pdf_page":27,"layer":"upper","title":"A further end and the inadequacy of a strict definition","arabic":null,"arabic_anchors":"«فيكون هذا كذا غاية الغاية» · «والعلم لا حدّ له بوجهه» · «واختاره الإمام الرازي لوجهين».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"In that case, this is the **end of the end**: a remoter result beyond the more immediate purpose of the science. The discussion then turns to *knowledge*. One position holds that it cannot be defined by a strict essential definition and instead must be made known in another way. The commentator reports that Imām Fakhr al-Dīn al-Rāzī preferred this view and adduces two arguments for it.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I014.png","stage":77,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Upper text, first-pass connected translation.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I014.upper.02","volume":1,"page":14,"physical_pdf_page":27,"layer":"upper","title":"Two arguments for immediacy","arabic":null,"arabic_anchors":"«الأول أن علم كل أحد بأنه موجود ضروري» · «وهذا أعم خاص والمطلق جزء منه» · «والثاني أن غير العلم يعلم بالعلم فلو علم العلم بغير العلم لزم الدور».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"First, everyone’s knowledge that **he himself exists** is necessary or immediate; this is a determinate case of knowing, and knowledge considered without that determination is more general. It is argued that, if the particular is immediate, then the more general conception should be no less so. Second, other things are known **by means of knowledge**; if knowledge itself could be known only by way of a further act of knowledge, a vicious circle or regress appears to threaten. The text specifies that the second objection bears against one who says that knowledge is known but **not** necessarily or immediately.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I014.png","stage":77,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Upper text close reading. The inferential move from particular to general is an **argument being reported**, not endorsed by the editor.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I015.lower.01","volume":1,"page":15,"physical_pdf_page":28,"layer":"lower","title":"Knowledge as an actuality of the knower","arabic":null,"arabic_anchors":"«حصول العلم» · «الضروري ... حصول علم جزئي بوجوده وهو غير تصوره» · «لم يصح وجهها إلا على عدم التحديد فقط».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal commentator explains that the occurrence of a particular knowledge is not the same as an explicit, reflexive conception of the nature of knowledge. A person can be aware of his existence without arranging a definition of cognition. If one uses such awareness to argue that knowledge resists **essential definition**, that is a more modest conclusion than showing that no explanatory account of knowledge can be given. The second proposition needs a separate proof.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I015.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Source-facing lower reading, not a literal complete mapping.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I015.lower.02","volume":1,"page":15,"physical_pdf_page":28,"layer":"lower","title":"Whether self-consciousness is unavoidable","arabic":null,"arabic_anchors":"«أن حصول العلم العلم لا يعني حصول النفس إلى الذي وحصوله فيها» · «يكون حصوله في النفس تصوراً وحكاية» · «بالدليل الثاني».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The margin considers whether every occurrence of a cognitive state includes awareness of that occurrence. It distinguishes the presence of the knowing **act** in the soul from a subsequent representation or conception **of that act**. If the two are identified, the claim that self-awareness is necessary may appear plausible; if distinguished, the claim needs qualification. The discussion leads to the second proposed route for making knowledge understood, namely division and example rather than a strict definition.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I015.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Several tightly printed clauses are insecure, especially the lead-in to I:16; the Arabic anchor is deliberately fragmentary.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I015.ruled.01","volume":1,"page":15,"physical_pdf_page":28,"layer":"ruled","title":"Conception of the acquired cognition","arabic":null,"arabic_anchors":"«(قوله وهو غير تصوره)» · «لكن تصوره لازم لحصوله كما في سائر الوجدانيات» · «اه منه».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “and it is not its conception”: nevertheless, one might contend that some conception is required for its occurrence, as with other objects of inner experience. Thus the distinction, while real, does not by itself establish that the cognition can occur without any accompanying apprehension of what is taking place. [Closing annotation has no positively established personal author.]","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I015.png","stage":77,"attribution":"unassigned separately ruled note","proof_note":"Short separately ruled note, provisional source reading.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I015.upper.01","volume":1,"page":15,"physical_pdf_page":28,"layer":"upper","title":"Resolving the first argument's equivocation","arabic":null,"arabic_anchors":"«على عدم التفرقة بين تصور العلم وحصوله» · «والضروري حصول علم جزئي بوجوده» · «وهو غير تصوره وغير العلم».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The objection rests on a **failure to distinguish between conceiving knowledge and its occurrence**. What is necessary here is the occurrence of a particular cognition of one’s own existence. That cognition's occurrence is not the same as the conception of the cognition, still less a universal definition of knowledge. Hence the first argument cannot simply carry the immediacy of one cognitive event over to the concept of knowledge as such.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I015.png","stage":77,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Upper text connected translation, with opening join from I:14.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I015.upper.02","volume":1,"page":15,"physical_pdf_page":28,"layer":"upper","title":"The objection from acquired conceptions","arabic":null,"arabic_anchors":"«أما ... حصول علم جزئي ... يتوقف تصوره على تصوره» · «وقيل لا يجدي ...» · «وإليه ذهب الغزالي».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"If the concept of knowledge is acquired, it is argued that some prior grasp of what one is acquiring may be required. Yet that cannot be established merely from the fact that a particular act of knowing has occurred. The discussion reports a further objection to the proposed distinction and associates a position in this dispute with al-Ghazālī. The crucial point is whether what requires a prior conception is **the acquired representation of knowledge**, or every instance of knowledge occurring in a knower.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I015.png","stage":77,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Upper passage partly compressed; attribution and precise final words should be rechecked before citation.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I016.lower.01","volume":1,"page":16,"physical_pdf_page":29,"layer":"lower","title":"Is the knowledge of a division itself known through knowledge?","arabic":null,"arabic_anchors":"«وحصول العلم به يستلزم إمكان العلم بأنه عالم» · «فيلزم حصول العلم بالعلم الخاص قبل حصول العلم بمطلق العلم» · «مفهوماً مطلق العلم».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The lower commentator contests the logic of the proposed division. Knowing by an act may permit one to know that one is a knower, but this does not mean the **unrestricted concept of knowledge** must have been defined before the particular act occurred. Conversely, if the mind has to grasp the general category before any example becomes intelligible, the explanatory procedure may tacitly presuppose what it was intended to provide. The point hinges on keeping distinct a concrete cognitive act, reflective awareness of that act, and the general concept of knowledge.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I016.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Connected reading of a major lower-register objection; unverified compressed subclauses remain.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I016.lower.02","volume":1,"page":16,"physical_pdf_page":29,"layer":"lower","title":"The particular and the general","arabic":null,"arabic_anchors":"«حصول العلم بالعلم الخاص» · «حصول العلم بالعلم الغير» · «مطلق العلم» · «ليس فقط».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal reasoning also asks how an item can be recognised as a **particular kind of knowledge** without prior conception of the general description. The author considers the contrary order as well: one might have a specific cognition and acquire a generic concept through subsequent comparison or reflection. That opposition is not resolved by simply calling either a particular or a general concept ‘necessary’; the alleged priority must itself be clarified.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I016.png","stage":77,"attribution":"unassigned lower printed commentary","proof_note":"Source-facing exposition, not all lower lines supplied in literal English; the final marginal clause continues to I:17.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I016.ruled.01","volume":1,"page":16,"physical_pdf_page":29,"layer":"ruled","title":"Why an example is not a definition","arabic":null,"arabic_anchors":"«(قوله وأما المثال)» · «يطلق على المشابه وعلى الجزئي» · «فالأول ... والثاني ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “as for the example”: *mithāl* can refer to something **similar** or to a **particular instance**. The text assigns the two examples their different roles accordingly. An illustrative instance can make a state recognisable without supplying the essential features demanded of a strict definition.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I016.png","stage":77,"attribution":"unassigned separately ruled note","proof_note":"Short ruled note, first visual reading; precise ending requires recheck.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I016.upper.01","volume":1,"page":16,"physical_pdf_page":29,"layer":"upper","title":"Four divisions of assent","arabic":null,"arabic_anchors":"«بالدليل الثاني وطريق معرفته عنده القسمة والمثال» · «الاعتقاد إما جازم أو غير جازم» · «والجازم إما مطابق للواقع أو غير مطابق» · «والمطابق إما ثابت أو غير ثابت».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The second route consists in making knowledge known through **division and example**. Under division: an assent is either firm or not firm; a firm assent is either in accordance with reality or not; and an assent in accordance with reality is either stable or unstable. In this way, one distinguishes certain knowledge from mere non-firm opinion, firm error, and even a correct belief that is not settled or secure. The divisions are supplied **to identify** knowledge, not as a strict definition giving its genus and essential differentia.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I016.png","stage":77,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Upper source text; each ternary split visually checked.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I016.upper.02","volume":1,"page":16,"physical_pdf_page":29,"layer":"upper","title":"Example and the limits of an essential definition","arabic":null,"arabic_anchors":"«وأما المثال فكأن يقال العلم إدراك البصيرة» · «كاعتقادنا أن الواحد نصف الاثنين» · «لا يحدّ بعبارة جامعة للجنس والفصل الذاتي» · «والإحساس به معروف».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Under example, one might speak of knowledge as the insight of the inner faculty, or point to our certain conviction that **one is half of two**. The intention of the thinker cited is not that the word can never be explained, but that a definition collecting an essential genus and difference is difficult or impossible in the present case. Many things are recognised perfectly well through experience or example without an analysis that displays their ultimate essence. The example helps a reader identify the intended state even where a genus-and-difference definition cannot be supplied.","reading_status":"source_facing_provisional_not_line_exhaustive","source_image":"source_images/I016.png","stage":77,"attribution":"Taftazani lemma within Sanandaji sharh","proof_note":"Upper source-facing reading; punctuation and the exact phrase concerning insight need verification against a second impression.","full_diplomatic_arabic":false,"all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false,"is_new_translation":true,"provenance":"source reread + inherited previous English + explanatory restatement; not certified","source_kind":"locating_arabic_anchors_only"},{"id":"I017.lower.01","volume":1,"page":17,"physical_pdf_page":30,"layer":"lower","title":"What is excluded by “complete disclosure”?","arabic":null,"arabic_anchors":"«المعلوم»؛ «صفة العلم»؛ «التصور المطابق والتصديق اليقيني»؛ «ليس الفصل ...»؛ «الظن».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The lower commentary tests the verbal definition of knowledge. If complete disclosure is taken to mean a **conception that correctly represents its object**, then a different condition must distinguish that from **certain assent** to a proposition. Otherwise a definition that works for knowledge by assent may be wrongly extended to every form of conception. Conversely, excluding opinion and uncertain supposition should not be construed as excluding every legitimate apprehension that is not accompanied by a proposition of assent. The author of the gloss cautions that defining a notion by its contrast with error can be useful in disputation but does not automatically explain the **nature of the cognitive act**. This portion is a source-facing English reading, not a word-for-word verified rendering of each compressed marginal line.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I017.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I017.lower.02","volume":1,"page":17,"physical_pdf_page":30,"layer":"lower","title":"Why the inquiry analogy matters","arabic":null,"arabic_anchors":"«(قوله وحقيقة النظر)»؛ «التصور والتصديق»؛ «لا تنحصر ...»؛ «الاستحضار»؛ «الانتقال».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"What matters in the definition of inquiry is that an investigator already possesses some terms, propositions, or general descriptions yet lacks the desired conclusion. Intellectual reflection arranges those items so that what was previously absent as a determinate cognition becomes present. “Movement” is not predicated equally of every case of perception, sensation, recall, or attention: it marks the **ordered search and transition** by which the intellect reaches a conclusion. The marginal writer asks whether this is truly a definition of every inquiry or a description of the **usual process**. The detailed dispute continues on I:18.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I017.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I017.ruled.01","volume":1,"page":17,"physical_pdf_page":30,"layer":"ruled","title":"The meaning of the movement of the soul","arabic":null,"arabic_anchors":"«(قوله حركة النفس) إطلاقاً للحركة على الانتقالات الواقعة للنفس من معقول إلى آخر»؛ «على سبيل التشبيه».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “movement of the soul”: motion is used **by analogy** for the transitions occurring in the mind from one intelligible object to another. The usual term for spatial movement is here applied to the intellect's passage through the stages of reasoning. The absence of physical distance does not eliminate the ordered differences between the starting question, premises, arrangement, and conclusion.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I017.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I017.upper.01","volume":1,"page":17,"physical_pdf_page":30,"layer":"upper","title":"Knowledge, disclosure, and recognition","arabic":null,"arabic_anchors":"«أو صفة يتجلى بها»؛ «أي ينكشف انكشافاً تاماً بذلك الصفة»؛ «(المذكور) كما من شأنه أن ينذكر ويلتفت إليه»؛ «إخراج الظن».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Another formula describes knowledge as “an attribute by which [the object] becomes disclosed”: through the attribute, the knowable is disclosed to the knower **completely**, so that the uncertain assent belonging to **opinion** (*ẓann*) is excluded. The thing known is called the “mentioned” or “recalled” object insofar as it can be brought into attention. These formulations are meant to mark the scope of the technical word *knowledge*, not to settle through a verbal substitution every philosophical dispute about what knowledge is. An imperfect apprehension, a complete assent, and a nonassertoric conception must remain distinguishable.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I017.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I017.upper.02","volume":1,"page":17,"physical_pdf_page":30,"layer":"upper","title":"Conception, apprehension, and terminological convention","arabic":null,"arabic_anchors":"«(إن فهمت) أي تلك المفردة»؛ «الإدراك المركب والكلي»؛ «يسمى إدراك البسيط أو الجزئي معرفة»؛ «(تنبيه على اختلاف الاصطلاحات)».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"If the object apprehended is simple or particular, a writer may call its apprehension **recognition** (*maʿrifa*); in other terminological arrangements the names “perception,” “conception,” and “knowledge” are distributed differently between simple and composite objects and between particulars and universals. Such a change in usage is a **difference of technical convention**, not proof that the object itself has changed. The author alerts the reader to the disagreements in terminology before defining deliberate inquiry (*naẓar*).","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I017.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I017.upper.03","volume":1,"page":17,"physical_pdf_page":30,"layer":"upper","title":"The motion of the soul in inquiry","arabic":null,"arabic_anchors":"«(وحقيقة النظر حركة النفس) من المطلوب المشعور به بوجهه ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"“The reality of inquiry is **a movement of the soul**” from a sought object which is known in some respect, or whose relevant question is already apprehended, toward matters by which it may be known. This movement is not a displacement of the soul through **physical space** but a transition between intellectual states. It begins with a question and proceeds toward the arrangement of what is known so as to reach what is not yet known. The sentence continues into I:18.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I017.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I018.lower.01","volume":1,"page":18,"physical_pdf_page":31,"layer":"lower","title":"On the stages of the mind's movement","arabic":null,"arabic_anchors":"«(قوله في المعقولات المحققة الخ)»؛ «الحركة الأولى والثانية»؛ «الترتيب المخصوص»؛ «المجهول».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal author considers which mental transitions are counted as the first movement and which as the return. It is possible to describe the investigator as turning from a general awareness of a problem toward its potentially relevant premises, and then directing the intellect from those premises, placed in a fitting **order**, to the desired conclusion. Some formulations count the acquisition of the conclusion as a further stage, while others treat it as the **terminus** of the second movement. These differences should not be conflated with the question whether the result itself follows by **custom**, by **generation**, or by a necessity of inference. That distinct issue is developed on I:24–26.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I018.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I018.lower.02","volume":1,"page":18,"physical_pdf_page":31,"layer":"lower","title":"If a proof that inquiry works itself requires inquiry","arabic":null,"arabic_anchors":"«(قوله لكون النظر مفيداً للعلم)»؛ «دور»؛ «الضرورة»؛ «النظر الصحيح»؛ «التصورات والتصديقات».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The margin records the objection that to prove inquiry effective through inquiry seems to assume the effectiveness it aims to establish. One reply says the general relation can be **known necessarily** or from an undeniable particular instance of valid reasoning. The critic responds that a particular act of obtaining knowledge may not of itself warrant the universal claim about all possible forms of inquiry. The difference between **actual valid reasoning** and any arrangement of statements matters: not everything that someone calls reflection succeeds in yielding an insight. The discussion thereby prepares the requirement that correct inquiry employ suitable premises and their appropriate order. A few closing lines on the form of a syllogism remain to be individually transcribed.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I018.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I018.upper.01","volume":1,"page":18,"physical_pdf_page":31,"layer":"upper","title":"Forward and returning intellectual movements","arabic":null,"arabic_anchors":"«في المعقولات ... (حركة أولى)»؛ «(عوداً)»؛ «(التحصيل) المطلوب (المجهول)»؛ «وأما الترتيب ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Inquiry occurs among **intelligible objects**. In one account it comprises an initial movement from the as-yet-unknown conclusion toward known matters that might establish it, and then a return, from the arranged premises toward **obtaining the conclusion**. The stages are counted differently depending on whether one includes the question's initial emergence, the collection of suitable premises, their arrangement, and the final apprehension. The cognitive movement is not a succession of physical events in spatial directions; it is a *methodological sequence* which renders a formerly unknown judgment knowable.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I018.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I018.upper.02","volume":1,"page":18,"physical_pdf_page":31,"layer":"upper","title":"Whether deliberate inquiry itself is theoretical knowledge","arabic":null,"arabic_anchors":"«(وكونه) أي النظر (مفيداً للعلم)»؛ «قال إنه لا يفيد أصلاً»؛ «لأن كون النظر مفيداً ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"“And whether it”—that is, inquiry—“produces knowledge”: this itself became a disputed proposition. Some deny that inquiry yields knowledge at all; others say that an inference from premises to a conclusion provides knowledge but disagree about **the mode of that provision**. Since proving that inquiry yields knowledge may itself require an act of inquiry, the sceptic threatens to make the proof circular. The text introduces the response that one must distinguish an immediately evident instance from an overarching inference concerning all inquiries, and an act's being a **means** from its being a **productive cause**.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I018.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I019.lower.01","volume":1,"page":19,"physical_pdf_page":32,"layer":"lower","title":"Whether knowledge of inquiry's usefulness is circular","arabic":null,"arabic_anchors":"«(قوله كون الواحد نصف الاثنين الخ)»؛ «(قوله يلزم إثبات إفادة النظر الخ)»؛ «دور»؛ «المقدمات»؛ «التصور والتصديق».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginal commentator contrasts the proposition “one is half of two” with acquired conclusions that require an arrangement of premises. If the proposition is **necessary**, it cannot serve without qualification as the example of a result acquired by investigative inference. If it is called *theoretical* in this context, one must specify how that description is being used. The objection about circularity likewise requires care: employing an inference to reach the proposition “some inference produces knowledge” may be circular if the inference's **trustworthiness** already depends upon that proposition as its premise. It does not automatically follow that a particular correct inference is invalid. To show why the form of the proof yields a conclusion, we need the premises, their connection, and the status of the result; a mere label “inquiry” does not suffice.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I019.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I019.lower.02","volume":1,"page":19,"physical_pdf_page":32,"layer":"lower","title":"Necessary premises, acquired conclusions, and the false regress","arabic":null,"arabic_anchors":"«العلم بكون المقدمات مستلزمة للنتيجة»؛ «التركيب»؛ «التصديق»؛ «الضرورة».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The margin further distinguishes **knowing the premises**, **knowing that they entail the conclusion**, and **knowing the conclusion**. The last can be novel even where the first two are already possessed, and in some cases awareness of the entailment becomes manifest in the very act of attending to the premises. The threat of an endless regress of proofs arises only if we demand a further inference to establish **each** relation in every case. The writer reports a contrary view that some such relations must be understood without further demonstration. These are disputes about the foundations of demonstration, not a dismissal of the value of reasoned inquiry.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I019.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I019.upper.01","volume":1,"page":19,"physical_pdf_page":32,"layer":"upper","title":"Disputed inference and the sphere of theology","arabic":null,"arabic_anchors":"«كون الواحد نصف الاثنين»؛ «وإن كان نظرياً لزم إثبات إفادة النظر بإفادة النظر»؛ «(وفي الإلهيات)»؛ «خلافاً للقائل بأنه لا يفيد العلم»؛ «(وبدون العلم)».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Consider the judgment that **one is half of two**. A necessity of this kind may be apprehended directly, but merely placing it in an argument does not establish that every formal reflection produces a new cognition. Where the effectiveness of inquiry is said to be theoretical, the sceptic alleges that it must itself be established by an inference—thus assuming the disputed effectiveness. The dispute is especially sharp “in matters divine,” where some thinkers deny that reasoning can provide knowledge of the objects at issue. The author distinguishes those divine truths which are understood by necessary cognition from those for which a proof can be offered. Denying the effectiveness of every inference merely because some truths are immediately evident would exceed what these examples establish.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I019.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I019.upper.02","volume":1,"page":19,"physical_pdf_page":32,"layer":"upper","title":"The sceptic's no-progress conclusion","arabic":null,"arabic_anchors":"«الحقائق الإلهية من ذاته وصفاته»؛ «التصور والتصديق»؛ «(وبدون العلم)»؛ «(ضروري) لا يحتاج إلى بيان».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Concerning divine things, it is argued that the essence and attributes of God do not fall under ordinary modes of conception and assent in the way everyday objects do. The reply is that one must not confuse **comprehending the divine essence** with **knowing propositions concerning God**. The latter may be accessible through demonstrative or inferential routes even if the former is beyond human comprehension. A further allegation—that proof must always presuppose the very conclusion sought—has to be stated precisely. Valid inquiry starts from something already known, not necessarily from the precise **conclusion** it is intended to establish.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I019.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I020.lower.01","volume":1,"page":20,"physical_pdf_page":33,"layer":"lower","title":"The syllogism about an originated world","arabic":null,"arabic_anchors":"«(قوله فإن الضروري قد يقع الخ)»؛ «العالم متغير وكل متغير حادث»؛ «العلم بأن العالم حادث»؛ «النظر مفيد للعلم».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “a necessary matter may be disputed, etc.” The writer suggests that we can know the usefulness of valid reasoning through a **particular correct instance** without descending into an endless series of justifications. The example is: **“The world is subject to change; everything subject to change is originated.”** From these premises comes knowledge that the world is originated. This furnishes an instance in which an inquiry leads to a conclusion. The argument should not be represented as if the word “inquiry” were itself a proof: the evidential force arises from the relevant premises and their proper relation.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I020.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I020.lower.02","volume":1,"page":20,"physical_pdf_page":33,"layer":"lower","title":"What is meant by knowing the effectiveness of inquiry?","arabic":null,"arabic_anchors":"«فالأثر المطلوب»؛ «هذه القضية»؛ «الموقف عليها»؛ «التصور والتصديق»؛ «الحكم على العام».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The margin examines what the general statement “inquiry produces knowledge” actually claims. Does it require knowing **every conceivable kind of inquiry**, or may the intellect reach a general recognition of a suitably specified kind from an evident example? If one must already know the general proposition in order to appreciate the example, the proposed demonstration begs the question; if one can recognize the effect in a clear instance and then identify the common features of the case, the threat of circularity is weakened. Yet the generalisation must not include **defective forms of reasoning** which do not satisfy the conditions for producing knowledge. The marginal author therefore distinguishes the **universal concept** of inquiry from its instances and asks what makes a premise-conclusion structure a proof.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I020.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I020.lower.03","volume":1,"page":20,"physical_pdf_page":33,"layer":"lower","title":"Why the teacher's authority does not replace proof","arabic":null,"arabic_anchors":"«(قوله لا يستلزم أن الحقائق الإلهية الخ)»؛ «المعلم»؛ «الاستدلال»؛ «المعرفة».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The concluding note turns toward the question of instruction. If someone says that divine knowledge cannot be obtained by inquiry and must depend on a **teacher**, then the teacher's authority must itself be evaluated. A hearer cannot establish the teacher's veracity simply by accepting that teacher's own claim to be truthful; nor will invoking one more teacher avoid the question. The argument is not that no one can **learn** from a teacher, but that independent **warrant** for believing the teacher cannot be replaced by an indefinite succession of unexamined reports. The main text pursues that objection on I:21.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I020.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I020.upper.01","volume":1,"page":20,"physical_pdf_page":33,"layer":"upper","title":"Disagreement over necessary matters","arabic":null,"arabic_anchors":"«فإن الضروري قد يقع فيه خلاف ...»؛ «والإلهيات ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Even a matter called **necessary** may be disputed, whether because a participant does not fully apprehend what is being asserted or because the disputant resists assent through obstinacy. The existence of disagreement does not by itself demonstrate that the matter lacks an evident foundation. The sentence then introduces the special case of divine realities and continues into I:21.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I020.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I021.lower.01","volume":1,"page":21,"physical_pdf_page":34,"layer":"lower","title":"Does learning require prior proof of the teacher's truth?","arabic":null,"arabic_anchors":"«(قوله لا يفيد إلا بعد العلم بصدقه الخ)»؛ «لا تحصل لنا فائدة العلم استقلالاً»؛ «صدق نسبة ...»؛ «خبر»؛ «النظر».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “it is of no benefit until his truthfulness is known”: the marginal writer objects to saying that a student's attainment of **any knowledge** requires a prior, independent demonstration that the teacher is trustworthy. What the principal argument needs is more exact: if a teacher's **report** is invoked as the decisive warrant for a disputed conclusion, the report's force rests on knowledge of its truthfulness. A learner may acquire or notice a true proposition on hearing the report without first articulating a proof of the speaker's character. The issue is not psychological occurrence but **epistemic warrant**. One should therefore not use the objection to deny the possibility of knowledge acquired from instruction; it attacks only the attempt to make unsupported teacher-authority foundational.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I021.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I021.lower.02","volume":1,"page":21,"physical_pdf_page":34,"layer":"lower","title":"Sense, experience, and the denial of common judgments","arabic":null,"arabic_anchors":"«(قوله اسم طائفة من الحكماء الخ)»؛ «من الشكوك»؛ «السوفسطائي»؛ «الحق ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The margin distinguishes a sincere **doubt** concerning a particular subject from a blanket denial of sensibles and first principles. It reports polemics against disputants who reject their own sensible experience or the axioms that make dispute meaningful. An asserted doubt is not answered simply by displaying additional testimony whose certainty the doubter has already rejected. The author suggests examining the exact **scope** of each denial: some reject the reports of particular senses, others accept ordinary appearances but deny the warrant of conclusions drawn from them, and still others claim to reject intellectual first principles. The ensuing I:22–23 debate concerns the latter distinction; no entire historical philosophical school can be inferred solely from this polemical name.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I021.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I021.upper.01","volume":1,"page":21,"physical_pdf_page":34,"layer":"upper","title":"A teacher's veracity cannot be warranted by that teacher alone","arabic":null,"arabic_anchors":"«لا يتصور بكلاهما ...»؛ «وأن إرشاد المعلم لا يفيد إلا بعد العلم بصدقه»؛ «فأما أن يعلم بالنظر فيكون النظر كافياً»؛ «وإلا لزم التسلسل».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"—the conceptions are not secured in the way demanded by the opponent. Even granting that they can be apprehended, we must ask what makes the instruction of a **teacher** a source of knowledge. That teacher's guidance yields no warranted result until his **truthfulness** has been known. If we know his truthfulness by examination, the necessity of a teacher is undermined, for the relevant investigation is already a possible path to knowledge. If we know it solely because he says that he is truthful, the explanation is circular: his testimony is authoritative only after the very truthfulness in question has been established. If a second teacher assures us of the first, then the second teacher's truthfulness must be known as well, threatening an indefinite regress. This is a proof against an **exclusive teacher-dependent epistemology**, not against the ordinary usefulness of teaching.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I021.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I021.upper.02","volume":1,"page":21,"physical_pdf_page":34,"layer":"upper","title":"Sophists, obstinacy, and the reported etymology","arabic":null,"arabic_anchors":"«(والمنكر) ... (معاند) لا يسمع دعواه»؛ «(السفسطائي) المنكر للحسيات أو الأوليات أو كليهما»؛ «السوف ... اللفظ اسم لطائفة من الحكماء».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"“The denier” of evident truths, insofar as he denies through obstinacy, is a **wilfully resisting opponent**, whose mere assertion does not overturn the original judgment. The name “Sophist” is applied in the text to one who denies sensible propositions, primary intellectual propositions, or both. The book reports an etymology from a word for **knowledge** and another for **error**, producing a characterization of a group said to misuse philosophical reasoning. This etymology is **reported from the historical author**, not endorsed by the translator as a modern linguistic finding.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I021.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I022.lower.01","volume":1,"page":22,"physical_pdf_page":35,"layer":"lower","title":"Reports of extreme scepticism and the senses","arabic":null,"arabic_anchors":"«والمحققون ... في العالم قوم ينتحل هذا المذهب»؛ «السوفسطائي»؛ «قوله قدح في الحسيات»؛ «البداهة».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The lower commentator reports that it is doubtful whether knowledgeable people consistently maintained a wholesale denial of sensibles and evident first principles; the group described in polemical accounts may instead have relied on exaggerated cases of illusion. In addressing the attack on perception, the relevant distinction is between **the sensation's occurring** and **an intellectual judgment about what the sensation shows**. Deceptive appearances may be corrected by another examination of the circumstances without granting that all judgments from the senses are suspect. The source compares several reported examples of sensory error, insisting that an error which arises from an **inference attached to perception** should not be described as a failure of all immediate cognition.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I022.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I022.lower.02","volume":1,"page":22,"physical_pdf_page":35,"layer":"lower","title":"The force of the example of noncontradiction","arabic":null,"arabic_anchors":"«(قوله من قدح في الأوليات الخ)»؛ «النفي والإثبات»؛ «إما أن يكون أو لا يكون»؛ «العلم بهذه القضية يتوقف على تصور الوجود والعدم».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The marginals then turn to the proposition that a thing cannot both exist and not exist in the same respect. The sceptic is right in a limited sense that one must understand the constituent terms to assent to the proposition. But that observation does not provide an independent **argument against its evident character**. A distinction must be made between **knowing the proposition itself** and **giving an explanatory proof of why the proposition is certain**. To demand a further proof that already assumes the proposition would be circular, but it does not follow that the immediate intellectual judgment is invalid. The lower discussion joins the fuller argument on I:23.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I022.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I022.ruled.01","volume":1,"page":22,"physical_pdf_page":35,"layer":"ruled","title":"“Immediate” refers to the intellect's immediate recognition","arabic":null,"arabic_anchors":"«(قوله والجواب أن البداهة) أي بداهة العقل لا الحس»؛ «(قوله إلى غير ذلك) أي من الطبعات العادية».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"“The answer is that immediate evidentness ...” means **the intellect's** immediate apprehension, not an attempt to prove the trustworthiness of a sense by appealing to that same sense. “And other cases” means other examples of customary or evident judgments. The second phrase is shortened in the print, so its ending is preserved here only as a locating anchor, not an authenticated full transcript.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I022.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I022.upper.01","volume":1,"page":22,"physical_pdf_page":35,"layer":"upper","title":"Why some perceptual errors cannot refute all sensible judgments","arabic":null,"arabic_anchors":"«قدح في الحسيات بأن حكم الحس قد يغلط»؛ «كما ترى الساكن متحركاً والمتحرك ساكناً»؛ «في بعض المحسوسات»؛ «الشمس مضيئة والنار محرقة».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Some attack **sensible judgments** by observing that the senses sometimes make mistakes. The observer may regard a stationary thing as moving or a moving thing as stationary: a person aboard a moving vessel may take it to be still and see the shore as moving. From cases like these the sceptic alleges that any judgment of sense is liable to error. The response is that an error in **some** instances does not establish that all perceptual judgments fail. There are cases, such as the recognition that the sun illuminates and fire burns, in which a properly formed judgment may be evident. The lesson is **not** that the senses are infallible, but that the transition from “some perceptual judgments are mistaken” to “none can constitute knowledge” lacks justification.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I022.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I022.upper.02","volume":1,"page":22,"physical_pdf_page":35,"layer":"upper","title":"The sceptic's challenge to excluded middle and contradiction","arabic":null,"arabic_anchors":"«قدح في الأوليات بأن أجل البديهيات قولنا النفي والإثبات لا يجتمعان ولا يرتفعان»؛ «ما أن يكون أو لا يكون»؛ «توقف تصور الوجود والعدم».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Others attack intellectual first principles. The most evident is said to be that **affirmation and denial cannot both obtain nor both fail to obtain** in the same respect: a proposition holds or it does not. The sceptic claims that even this judgment relies on the prior conceptions of **being and nonbeing**, and perhaps on our notion of predication itself. If those notions must first be reached through proofs relying on the very judgment being defended, the proof turns in a circle. The issue passes into I:23, where the main text and commentary distinguish the **judgment's being immediate** from a purported demonstration of its necessity.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I022.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I023.lower.01","volume":1,"page":23,"physical_pdf_page":36,"layer":"lower","title":"Parsing the circularity argument correctly","arabic":null,"arabic_anchors":"«(قوله ... نظراً إلى ذاته)»؛ «(قوله توقف لا محالة الخ)»؛ «الانظار المتقدمة»؛ «المقدمة»؛ «الدور».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The margin considers the grammar of “it depends inevitably.” It ought to be construed as the **consequence of the stated supposition**, rather than as an incidental description of a class of investigations. Otherwise one could mistakenly infer that the author assumes certain forms of inquiry escape the very principle under examination. The consequence is that **a circle follows** when the proof of a basic proposition is made dependent on a reasoning process that already needs it. The note distinguishes the **antecedent of a conditional objection** from the **asserted conclusion**, and warns against treating a hypothetical assumption as the author's own positive position.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I023.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I023.lower.02","volume":1,"page":23,"physical_pdf_page":36,"layer":"lower","title":"Conception before assent does not imply inferential proof","arabic":null,"arabic_anchors":"«(قوله لازمة بها)»؛ «(قوله من غير نظر واستدلال الخ)»؛ «التصورات البديهية»؛ «أطرافها»؛ «دلالة المعجزة».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Assent to a proposition requires **grasping its terms**, but that does not entail that the proposition's certainty must arise from a discursive syllogism. The marginal writer compares immediate conception of terms, the immediate **judgment** relating them, and the separate process of **inferring** a conclusion. Confusing these yields a fallacy: a proposition may be known after its terms are understood without having been *proved* by a prior inference. The note also asks how an obvious proposition could be defended to someone who refuses the status of all obvious judgments, and why a verbal appeal to a teacher would merely reinstate the earlier dependence problem. The final lower clauses point toward the question whether correct reflection leads to knowledge by necessity, custom, or generated action.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I023.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I023.upper.01","volume":1,"page":23,"physical_pdf_page":36,"layer":"upper","title":"Subject, predicate, and the danger of a circle","arabic":null,"arabic_anchors":"«وعلى تحقيق معنى كون الشيء موضوعاً وما يكون محمولاً»؛ «توقف لا محالة على حقيقة هذه القضية»؛ «الكل أعظم من الجزء»؛ «فلزم الدور».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The challenge asks for a conception of what it means for something to be **subject** and for another thing to be **predicated** of it. But if the very idea of predication presupposes the actuality of the law concerning affirmation and denial, our attempt to demonstrate that law from something prior will be circular. For example, a proof about the proposition **“the whole is greater than the part”** may already rely on excluding its contradictory alternative. If such a proof is required before the intellect can assent to the fundamental proposition, the proof has presupposed the principle it was meant to establish. The source states this as an objection to the **order of demonstration**, not to ordinary use of true judgments.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I023.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I023.upper.02","volume":1,"page":23,"physical_pdf_page":36,"layer":"upper","title":"Certain intellectual assent as the terminus","arabic":null,"arabic_anchors":"«العقل جازمة بها من غير نظر واستدلال»؛ «ومنهم من قدح فيها جميعاً»؛ «وهو معلوم».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The reply is that the intellect's judgment in this case is **decisive without inquiry or inference**. A person may nevertheless dispute it verbally or construct a conditional argument that seems to undermine it. The existence of that dispute does not show that a first principle **must** be proved through another first principle before it can be known. If every fundamental judgment had to be derived from something yet more fundamental, demonstrations could never begin. The relevant discussion now turns from the reality of evident knowledge to its occurrence after **deliberate investigation**.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I023.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I024.lower.01","volume":1,"page":24,"physical_pdf_page":37,"layer":"lower","title":"Distinguishing custom, necessity, and generation","arabic":null,"arabic_anchors":"«(قوله بطريق العادة) أي تكرر ذلك دائماً مع جواز أن يتخلف ...»؛ «(قوله فاعل مختار)»؛ «(قوله أو التوليد الخ)»؛ «لو كان مولداً للعلم ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “by way of custom”: the regularity is said to recur while an exception remains **possible**; if an exception occurs, the regular sequence has not thereby been shown to be metaphysically necessary. On the phrase “a choosing agent”: God's freedom is intended, in contrast with the philosophers' overflowing cause. On “or generation”: the marginal writer tests what the phrase actually entails. If reflection **generated** knowledge, the actor's performance of the reflection would have to supply more than the mere temporal antecedent of the result. The first act and the purportedly generated second act must be distinguished. The opponent may ask what prevents reflection from taking place without the knowledge, and whether the claim that such failure is impossible is itself a claim about **productive necessity** rather than generation. This prepares the objection at I:25 that knowledge is not in the category of action. **Reading caution:** The printed lower annotation contains one additional tightly compressed argument around the first act's capacity; this English follows the argument's order but remains below whole-page literal certification.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I024.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I024.ruled.01","volume":1,"page":24,"physical_pdf_page":37,"layer":"ruled","title":"The Ashʿarite theologians' principle","arabic":null,"arabic_anchors":"«(قال المصنف رحمه الله بطريق العادة) هذا مذهب الأشعري»؛ «الممكنات بأسرها مستندة إلى الله تعالى ابتداء»؛ «عقيب النظر الصحيح بإجراء العادة».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The author, may God have mercy on him, said: “by way of custom.” This is the Ashʿarī position. They hold that all possible things are attributed to God **in the first instance**, and that one possible event does not independently produce another. Instead, God brings one thing into being after another in a customary order. When that order recurs, it is called **custom**; when it differs from the ordinary order, one speaks of an exception to custom. The knowledge arising after sound investigation is an originated contingent event regularly accompanying the investigation, so it is accounted for through God's customary action. This note treats **succession without independent necessitation**, not a denial that inquiry has practical epistemic significance.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I024.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I024.ruled.02","volume":1,"page":24,"physical_pdf_page":37,"layer":"ruled","title":"The Muʿtazilite principle","arabic":null,"arabic_anchors":"«(قال رحمه الله أو التوليد) هذا ما ذهب إليه المعتزلة»؛ «الأفعال الاختيارية صادرة عنا»؛ «فإما أن تكون صادرة عنا بالمباشرة ...»؛ «بواسطة فعل آخر منا».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"He said, God have mercy on him: “or generation.” This is the position attributed to the Muʿtazilites. On their account, our **voluntary acts** issue from us. They occur either by **immediate performance**, when no other action of ours mediates them, or by **generation**, when one of our acts produces another through an intermediate act of ours. They say that the knowledge that arises after rational examination is produced through the examination and thus is an instance of generation. The source's next page defines the two modes more precisely.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I024.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I024.upper.01","volume":1,"page":24,"physical_pdf_page":37,"layer":"upper","title":"The Ashʿarite account of customary conjunction","arabic":null,"arabic_anchors":"«مما سبق رداً واستدلالاً (وهل هو) أي كون النظر مفيداً للعلم (بطريق العادة)»؛ «بناء على أن جميع الممكنات مستندة إليه تعالى عندنا ابتداء»؛ «وأنه تعالى قادر مختار».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"After the preceding argument and reply the text asks: **How does investigation bring about knowledge?** “Is it by way of **custom** (*ʿāda*)?” This follows the doctrine that every possible event depends directly, in its origination, on God, exalted is He, and that He is **able to choose**. Nothing among possible events therefore proceeds from Him with the necessity of a self-sufficient cause. Knowledge may regularly follow correct inquiry because God creates it in that order, without the inquiry's being a productive cause by its own inherent power.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I024.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I024.upper.02","volume":1,"page":24,"physical_pdf_page":37,"layer":"upper","title":"The Muʿtazilite alternative of generation","arabic":null,"arabic_anchors":"«(أو) بطريق (التوليد)»؛ «بناء على أن ليس الكل مستنداً ...»؛ «يجب عنه صدور شيء ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"“Or [is it] by way of **generation** (*tawlīd*)?” This follows the account under which the acts of a voluntary creature can give rise, through the mediation of one of its own acts, to further effects. Correct reflection, on that account, can be an agent's act through which knowledge is generated. The definition and the hand–key example appear at the beginning of I:25; the source must be read **continuously**, not as an isolated assertion that knowledge is just another bodily act.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I024.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I025.lower.01","volume":1,"page":25,"physical_pdf_page":38,"layer":"lower","title":"“Acting” and the hand–key example do not classify knowledge as physical motion","arabic":null,"arabic_anchors":"«(قوله واعترض بأن العلم الخ)»؛ «النظر على أكثر تقديراته أيضاً ليس من مقولة الفعل»؛ «أرادوا بالفعل هذا الأمر الحاصل بالفاعل لا نفس التأثير»؛ «حركة اليد وحركة المفتاح»؛ «فعل واحد».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On the objection “knowledge is not [of the category of] acting”: the commentator observes that even investigation itself, in its most carefully qualified sense, does not simply belong to the category of action. What those employing the analogy intended by an “act” was **something obtained through an agent**, not necessarily the metaphysical category of action as a separate accident inhering in the agent. The disputants agree that the hand's movement and the key's movement may be attributed to an agent, though the movement, considered in its own category, is not strictly an instance of the category *acting*. There is therefore no warrant to force the knowledge–investigation relation into the taxonomy of bodily movements.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I025.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I025.lower.02","volume":1,"page":25,"physical_pdf_page":38,"layer":"lower","title":"The act, the intermediary, and the voluntary origin of inquiry","arabic":null,"arabic_anchors":"«(قوله الفعل الآخر ... الخ)»؛ «فإن الفعل الآخر في التوليد لا بد أن يكون فعلاً واحداً»؛ «(قوله من المبدأ الفياض الخ)»؛ «الروح والكتاب المبين»؛ «سلب الاختيار منه تعالى».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"In the expression “the other act” it is necessary to specify what is meant by the intermediary in a generated action. If the first action occurs through a person's own capacity and choice, that is not yet sufficient to show that every subsequent outcome belongs to the same act of choice **without a further question about causality**. The margin presses the distinction between the first voluntary act and its purportedly generated effect. The language of an overflowing principle, on the other hand, was introduced to explain a supposed necessary emergence from a cause prepared to give an effect. In the theologians' criticism, however, making the relationship simply necessary would compromise the divine **freedom of choice**. The marginal discussion closes by moving toward the contrast stated at the top of I:26. **Proof limitation:** The compact lines connecting these arguments contain quotations and allusions that require full typed Arabic collation; the current English follows the sequence but does not claim word-for-word certainty.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I025.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I025.ruled.01","volume":1,"page":25,"physical_pdf_page":38,"layer":"ruled","title":"The philosophers' overflowing cause and a fourth position","arabic":null,"arabic_anchors":"«(قال قدس سره أو الوجوب) هذا ما قاله الحكماء»؛ «المبدأ الفياض لوجود الحوادث موجب بالذات»؛ «العلم الحاصل عقيب النظر أمر حادث»؛ «مذهب آخر اختاره الإمام الرازي والغزالي وإمام الحرمين»؛ «حصول العلم عن النظر الصحيح لازم له لزوماً عقلياً غير متولد منه».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"He said, may his spirit be sanctified, “or necessity.” This is what the philosophers maintain, building on the principle that the overflowing source entails the occurrence of originated effects **by its essence**, while their issuance from it depends on the receiver's complete preparedness. Since knowledge that follows inquiry is originated, it falls under that general rule. But another opinion—reported as the choice of Fakhr al-Dīn al-Rāzī, al-Ghazālī and Imām al-Ḥaramayn—has not been included in the main enumeration: knowledge follows **sound investigation** by a **rational entailment**, without being generated by it as the Muʿtazilites suppose. The note's final personal formula is not sufficient by itself to identify the glossator.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I025.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I025.upper.01","volume":1,"page":25,"physical_pdf_page":38,"layer":"upper","title":"Generation is action mediated through another act","arabic":null,"arabic_anchors":"«ومعنى التوليد هو أن يصدر من الفاعل فعل بواسطة فعل آخر صادر منه»؛ «كحركة اليد للمفتاح»؛ «وبقباله المباشرة وهي أن يصدر منه فعل بلا واسطة».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"[The Ashʿarite account holds that] God, exalted is He, brings the effect about **directly**. The meaning of “generation” (*tawlīd*) is that one act proceeds from an agent **by means of another act which also proceeds from that agent**. An example is the movement of the hand and of a key: the movement of the key takes place through the movement of the hand. Opposed to such generation is **immediate agency** (*mubāshara*), namely the production of an act without an intervening act. These definitions explain the parties' different analyses of how knowledge follows examination; the hand–key analogy is not a proof that knowledge literally is a movement.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I025.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I025.upper.02","volume":1,"page":25,"physical_pdf_page":38,"layer":"upper","title":"Is knowledge in the category of action? The alternative of necessity","arabic":null,"arabic_anchors":"«واعترض بأن العلم ليس من مقولة الفعل»؛ «وأجيب بأن الفعل الآخر هنا إفادة العلم وهي فعل»؛ «(أو الوجوب)»؛ «فيضان الحوادث من المبدأ الفياض عند الاستعداد التام القابل واجب».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"It was objected that **knowledge is not an instance of the category of acting**. The reply is that what is being called the additional “act” here is **imparting knowledge** (*ifādat al-ʿilm*), which can be described as acting. “Or by necessity”: this is the third explanation, according to which the issuance of originated things from the overflowing principle is **necessary** upon the complete preparation of what is to receive them. The expression concerns the **mode of dependence of the effect on its principle**, not a claim that the act of inquiry is itself the substance of knowledge.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I025.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I026.lower.01","volume":1,"page":26,"physical_pdf_page":39,"layer":"lower","title":"The fourth position chosen by al-Rāzī and reported by al-Ghazālī","arabic":null,"arabic_anchors":"«(قوله فيه خلاف بين الأشاعرة الخ)»؛ «الإمام الرازي»؛ «حجة الإسلام ... مذهب أكثر أصحابنا»؛ «النظر يستلزم العلم بالنتيجة بطريق الوجوب»؛ «من غير أن يكون النظر علة ... أو مولداً».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On the phrase “there is disagreement among the Ashʿarites”: the writer recalls a further opinion selected by Imām al-Rāzī; al-Ghazālī reports it as that of many among “our associates.” It holds that investigation **entails** knowledge of its conclusion by way of necessity, **without** investigation being the productive cause posited by the philosophers or the generating act posited by the Muʿtazilites. It is not enough to say merely that the knowledge **usually** follows the inquiry; that would return us to the position of customary association. The intended entailment is logical or rational: when the investigator has actually grasped the relevant premises and their implication, the conclusion cannot fail to follow as an item of knowledge. This necessity must not be equated automatically with a necessitating agent's independently producing an effect.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I026.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I026.lower.02","volume":1,"page":26,"physical_pdf_page":39,"layer":"lower","title":"Does that necessary entailment conflict with divine agency?","arabic":null,"arabic_anchors":"«لو امتنع أن لا يقع بأن لا تتعلق به قدرته واختياره»؛ «كون العلم أثر القادر المختار وجائز الفعل والترك»؛ «جواز الترك بمعنى امتناع ...»؛ «العلم ضروري عند ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The margin tests whether the position can preserve God's being a **powerful agent who chooses**. If saying that the result of sound investigation is necessary means that God could not refrain from granting knowledge even where His power and will did not attach to it, it would not describe the theological position as intended. Yet it is also possible to say that the effect is brought about by a voluntary agent and nevertheless follows necessarily **given the complete supposition under which that agent actually brings it about**. The possibility of refraining must not be understood as the simultaneous occurrence of two contradictory outcomes under precisely the same total conditions. The dispute is therefore over what remains fixed when a speaker asserts the possibility of an act and of its omission. Necessity of **inference** need not abolish divine choice; nor may freedom of choice erase the necessity by which the investigator recognises a valid consequence. **Proof limitation:** The final compact qualifications of “possible omission” are paraphrased and require another Arabic/English line comparison.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I026.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I026.ruled.01","volume":1,"page":26,"physical_pdf_page":39,"layer":"ruled","title":"Knowledge as certain assent","arabic":null,"arabic_anchors":"«(قوله لأجل حصول اليقين) إشارة إلى أن في التعليل والمعرفة بمعنى التصديق اليقيني»؛ «المعرفة المتعلقة بالجزئي ... بالإحساس».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “for obtaining certainty”: the gloss indicates that “knowledge” and “recognition” here mean **certain assent**. Knowledge concerning a particular may be attained through sensation; that is not the debated inferential recognition of God. A predication of certainty and the means by which an object is apprehended must be distinguished.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I026.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I026.upper.01","volume":1,"page":26,"physical_pdf_page":39,"layer":"upper","title":"The theological disagreement","arabic":null,"arabic_anchors":"«وهذا مبني على سلب الاختيار عنه تعالى علوّاً كبيراً»؛ «(فيه خلاف) بين الأشاعرة والمعتزلة والفلاسفة»؛ «(والنظر في معرفة الله تعالى) أي لأجل حصول اليقين».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"This last position rests on denying freedom of choice to God—exalted is He far above that. “Concerning this there is disagreement” among the Ashʿarites, Muʿtazilites, and philosophers, in the order stated. “Investigation into the knowledge of God, exalted is He” means inquiry **for obtaining certainty**. The predication “is obligatory” follows at the top of I:27; it must not be attributed to the margin on this leaf.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I026.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I027.lower.01","volume":1,"page":27,"physical_pdf_page":40,"layer":"lower","title":"Obligatory according to what gives rise to the obligation","arabic":null,"arabic_anchors":"«(قوله واجب الخ) أي شرعاً إن كان وجوب الواجب المطلق شرعياً وعقلاً إن كان عقلياً»؛ «في شرح المقاصد».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “obligatory”: that means **obligatory by revealed law**, if the unconditional obligation whose means are at issue is itself established by law; and **obligatory by reason**, if the principal obligation is rational, as stated in *Sharḥ al-Maqāṣid*. Merely saying “obligatory” without identifying the source of the principal duty leaves the point ambiguous.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I027.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I027.lower.02","volume":1,"page":27,"physical_pdf_page":40,"layer":"lower","title":"The celebrated premise and the cause/condition disagreement","arabic":null,"arabic_anchors":"«واعلم أن في هذه المقدمة المشهورة اختلافاً وفي بيانها اضطراباً»؛ «أن المقدور الذي يتوقف عليه الواجب المطلق واجب بوجوبه مطلقاً»؛ «سواء كان سبباً له أو شرطاً»؛ «لو لم يجب لجاز ترك الواجب المتوقف عليه»؛ «مع بقاء التكليف».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Know that the well-known premise is disputed, and its exposition has been unsettled. Most writers say that what is **within the agent's power**, and upon which an unconditioned duty depends, is itself obligatory **by virtue of that duty**—whether it is called a **cause** or a **condition**. They argue: if the prerequisite were not obligatory, leaving it undone would be permitted. Yet leaving it undone necessarily prevents performance of the commanded act. The agent would then be allowed to omit the very thing he is supposedly commanded to do. Another formulation argues that, if the prerequisite were not obligatory while the duty continued to bind, the commanded act would be demanded in the absence of a necessary condition and thus would be **impossible to perform**. Both forms of the proof assume that the agent can obtain the missing prerequisite; one must not silently carry the claim over to what lies wholly outside his power.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I027.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I027.lower.03","volume":1,"page":27,"physical_pdf_page":40,"layer":"lower","title":"Disagreement over whether a condition is itself commanded","arabic":null,"arabic_anchors":"«وذهب قوم إلى عدم وجوب مقدمته مطلقاً»؛ «واختاره قوم إذا كان سبباً لا شرطاً»؛ «أما السبب ...»؛ «فكا الشرط»؛ «ليس مقصود الشارع بالطلب».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Others deny that an indispensable prerequisite acquires a **separate obligation** simply because the principal act is commanded. Some distinguish the **cause** from a **condition**, alleging that a cause is closely connected with producing the effect, whereas a condition only removes an impediment to the act's becoming performable. But the margin replies that the proximity of a cause to its effect, by itself, does not establish that the lawgiver has made that cause a separate object of command. A condition may be indispensable while its attainment remains a distinct question. The parties must distinguish the **legal object commanded** from the **means through which it can be performed** and from the circumstances under which the obligation is first activated.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I027.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I027.lower.04","volume":1,"page":27,"physical_pdf_page":40,"layer":"lower","title":"Conditional obligation, absolute obligation, and permission to omit the means","arabic":null,"arabic_anchors":"«فالأشهر جواز الترك»؛ «الوجوب بالشرط»؛ «أمر الأصل»؛ «استلزام إيجاب الذي يجب بمقدمته ... وجوب مقدمته»؛ «كما هو الظاهر».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"If a duty is itself **conditional**, absence of the condition may mean that no present obligation arises; that cannot be treated as identical to leaving undone a necessary means **after** an unconditional duty is already binding. The marginals test a formulation that says the lawgiver's demand for an end indirectly requires the indispensable means, without specifying those means as separate ends of worship. On another formulation, absence of an explicit command concerning the means allows the actor to leave them aside, which would undermine the effect of the principal obligation. Whether that conclusion follows depends on what “permitted to omit” means. If omission of the means is permitted **as a means of omitting the commanded end**, the position is inconsistent with the end remaining obligatory. If, instead, the text is silent regarding a **second independent command**, there is no contradiction merely on that account. The argument continues on I:28, and its full proof turns on the scopes of **obligation**, **condition**, and **permission**. The margins are **not** silently assigned to Muḥammad Wasīm.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I027.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I027.upper.01","volume":1,"page":27,"physical_pdf_page":40,"layer":"upper","title":"Conclusion of the main-text sentence","arabic":null,"arabic_anchors":"«لوجوده (واجب)».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"“... [investigation for establishing] His existence **is obligatory**.” The text closes the sentence started on I:26. **No further principal commentary is printed on I:27**: the rest of the page is the separately printed marginal debate.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I027.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I028.lower.01","volume":1,"page":28,"physical_pdf_page":41,"layer":"lower","title":"Distinguishing non-obligation from the permitted omission of a prerequisite","arabic":null,"arabic_anchors":"«التعليلات»؛ «فلا يكون قول القائل بعدم الوجوب واقعاً على طرف النقيض»؛ «إمام الحرمين»؛ «وجوب مقدمة ... بتحصيل ذلك الذي بدونها أولاً».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"These explanations do not show that everyone who denies a **separate obligation for the prerequisite** contradicts everyone who says the prerequisite must be procured. Much of the dispute turns on a change in the proposition's subject. The attributed explanation of the position of Imām al-Ḥaramayn concerns the duty of acquiring **an indispensable condition that the lawgiver requires the agent to bring about**, not the wholly general assertion that every condition on which a command depends must always be under a prior independent command. If the condition is not within the agent's control, or if the end has not yet become binding, the earlier proof cannot be applied without qualification. This is why the marginal writer resists treating the different formulas as a simple pair of contradictories.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I028.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I028.lower.02","volume":1,"page":28,"physical_pdf_page":41,"layer":"lower","title":"No contradiction between an unconditional duty and the need for means","arabic":null,"arabic_anchors":"«لا يلزم أن يكون الوجوب مشروطاً بالمقدمة»؛ «عدم الوجوب للمقدمة»؛ «التكليف بما لا يطاق»؛ «التكليف بالواجب الذي بدون وجود المقدمة»؛ «إطلاق الواجب المطلق».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The fact that the commanded action cannot occur **without** its prerequisite must be distinguished from saying that its **being obligatory** depends on the prior attainment of that prerequisite. To command the act **without allowing the existence of its indispensable means** would indeed be to demand what cannot be done. But commanding the act while not separately declaring the prerequisite obligatory is another proposition. Silence about a separate command does not establish that the means may be left unprocured; likewise, the general command does not by itself specify each candidate means and whether it is necessary in the relevant case. The margin criticizes arguments that alternate between these senses of a “conditional” or “unconditional” duty without notice.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I028.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I028.lower.03","volume":1,"page":28,"physical_pdf_page":41,"layer":"lower","title":"What the expression “the capable prerequisite” excludes","arabic":null,"arabic_anchors":"«(قوله أمر مقدور الخ)»؛ «يتعلق به القدرة أو غير فعل»؛ «(قوله المعرفة الواجبة الخ)»؛ «العلم بالقادر»؛ «متعلق الخطاب».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The qualification “a matter within one's power” is not idle. An indispensable background circumstance which the agent cannot bring about is not commanded in the same manner as an accessible act of preparation. In certain examples, an agent's power is related to an actual performance rather than to every antecedent condition of that performance; the terminology must follow the thing that the command **addresses**. Likewise, in the phrase “obligatory knowledge,” the obligation concerns the attainment of recognition of God. When examination is the available means for a legally accountable person to reach it, the dispute is whether that available means is itself commanded **as a means** and whether its necessity can be inferred from the obligation of the end. The closing marginal clause introduces the qualifications to “unconditional obligation” taken up in I:29. **Reading caution:** Compact source expressions regarding capability and addressee remain to be individually transcribed and proofed.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I028.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I028.upper.01","volume":1,"page":28,"physical_pdf_page":41,"layer":"upper","title":"Proof from texts, consensus, and the agent's power","arabic":null,"arabic_anchors":"«(بالنص) أي الكتاب والسنة (والإجماع) واتفاق الأمة على وجوبه»؛ «(ولكونه) أي النظر أمراً مقدوراً»؛ «(مقدمة للمعرفة الواجبة عند ذلك)».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"Investigation is obligatory “by the [revealed] text”—that is, scripture and the Sunna—“and by consensus,” meaning the community's agreement on the obligation, “and because it”—investigation—“is a matter within one's power, and a prerequisite of the knowledge that is obligatory.” The last clause presupposes the argument over **obligatory means**, developed throughout the extensive marginal commentary on I:27–29. The sentence at the bottom of the upper register continues immediately into the top of I:29.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I028.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I029.lower.01","volume":1,"page":29,"physical_pdf_page":42,"layer":"lower","title":"Objections to an obligation established by text and consensus","arabic":null,"arabic_anchors":"«(قوله أي بالنص والإجماع الخ)»؛ «فاعلم أنه لا إله إلا الله»؛ «ليس بقطعي الدلالة»؛ «بل يدعي الخصم الاكتفاء بالتقليد»؛ «وأجيب بأن الظن كاف في الوجوب الشرعي»؛ «دليل إجمالي»؛ «فرض عين ... فرض كفاية».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “that is, by scripture and consensus”: it has been denied that proof has been established that **knowledge must be obtained by investigation**. As to the scriptural text, the Almighty's saying, “Know that there is no deity but God,” is not decisive as a proof of obligation: the imperative is not invariably employed for obligation. As to consensus, the objection is that its transmission in this particular matter is not decisive. The opponent claims that **uncritical reliance on authority** suffices, pointing out that the Companions accepted professions of faith from common people without demanding the procedures of learned disputation, verification, and demonstration. The answer is that a **probable indication** may suffice to establish an obligation of religious law, and the Companions' acceptance of ordinary believers does not show that those believers lacked every proof. They could possess recognition resting on **general indications**. The margin therefore distinguishes two demands: possessing an elementary indication that raises one above mere imitation is an **individual duty**; possessing sufficiently detailed argumentation to remove sophistical doubts is a **collective duty**. The source signals that a related question returns towards the close of the book. This is a *reported dialectic*, not an editorial declaration that all Muslims actually carried out formal demonstrations.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I029.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I029.lower.02","volume":1,"page":29,"physical_pdf_page":42,"layer":"lower","title":"The disputed extension of “unconditional”","arabic":null,"arabic_anchors":"«ليس معنى الواجب المطلق ما يكون وجوبه على جميع التقادير والأحوال»؛ «ما من واجب إلا وهو مقيد ببعض التقادير»؛ «تحصيل الحاصل»؛ «لو نظر وجبت المعرفة وإلا فلا»؛ «مقيد بوجود مقدمتها ... لا بوجوب مقدمتها».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On the expression “the unconditionally obligatory”: it does **not** mean an act obligatory under every conceivable supposition and circumstance. That would leave nothing whatsoever unconditionally obligatory. Every duty is subject to some qualifications; at the least, a duty is not imposed anew under the supposition that precisely what is demanded has already been performed, since this would amount to **acquiring what has already been acquired**. Rather, the relevant point is that a duty is not conditioned, *as regards its becoming binding*, upon independently requiring the agent first to acquire the prerequisite. The disputed analysis can be expressed by saying that the knowledge whose obligatory character is being discussed may be obligatory whether the person has investigated or has not yet investigated, while **the emergence of the knowledge** still depends on the investigation in its proper order. The margin disputes a formula that makes the main duty obligatory only if its prerequisite has already occurred; in that formula, the prerequisite's **existence** is treated as a condition for the obligation, which is the reverse of the unrestricted duty being analysed. **Reading caution:** The dense final lines distinguish several scopes of “conditioned on a prerequisite,” and their pronoun references require a final Arabic transcription before this can be classed as literal complete.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I029.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I029.ruled.01","volume":1,"page":29,"physical_pdf_page":42,"layer":"ruled","title":"What an unconditional obligation means","arabic":null,"arabic_anchors":"«(قوله الواجب المطلق) المراد بالواجب المطلق أن لا يكون وجوبه مقيداً بما يتوقف عليه، كتوقف الزكاة على حصول النصاب منه».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On his words “the unconditional obligation”: what is intended is an obligation **whose binding force is not conditioned upon a prerequisite required for its performance**, unlike the obligation of the alms-tax, which is conditioned upon the attainment of the legally specified minimum holding (*niṣāb*). The note concerns the **condition for a duty's becoming binding**, not the claim that duties can be performed without their means.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I029.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I029.upper.01","volume":1,"page":29,"physical_pdf_page":42,"layer":"upper","title":"Closing the proof from the obligatory means","arabic":null,"arabic_anchors":"«أي بالنص والإجماع والمقدور الذي كان مقدمة وهو قوله فالواجب المطلق».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"—that is, **by scriptural text and consensus**, and with respect to the prerequisite **within one's power**, which was the earlier premise of the argument, namely the statement: “Therefore the unconditional obligation …” The sentence is continued from I:28 and the following upper argument begins on I:30. One must not make this isolated upper line into a separate complete proof.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I029.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I030.lower.01","volume":1,"page":30,"physical_pdf_page":43,"layer":"lower","title":"What is presupposed in demanding inquiry into a miracle","arabic":null,"arabic_anchors":"«(قوله وفي جميع ما يتوقف ثبوته على ثبوته الخ)»؛ «إن الشرع موقوف على ثبوت الصانع وإرساله الرسول والتصديق له بالمعجزات الباهرة»؛ «فلو قال النبي صلى الله عليه وسلم انظر في هذه الأمور ...»؛ «النظر يمكن الحصول وإن لم يجب»؛ «إلزام النبي ... على غير الواجب».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On his words “and in everything whose establishment depends upon its establishment”: the establishment of the law is dependent on establishing the Creator, His sending a messenger, and the messenger's truthfulness through manifest miracles. The proofs of those matters involve inquiry. If the Prophet tells someone to examine the matters—including the miracle—upon which the authority of religious prescriptions depends, that person might object: “I shall not investigate until this religious obligation is proved to me.” But the authority claimed for that obligation is itself among the things that require inquiry. The reply acknowledges that **inquiry can take place without its having first been commanded**: what is possible to perform need not already be obligatory. Yet the point at issue is the Prophet's **binding demand** for inquiry; an obligation to comply does not follow from mere feasibility. The marginal argument therefore separates a person's ability to investigate from the authority to **compel** him to investigate. It concludes by returning to the danger of making the sending of prophets ineffective under the proposed circular dependency. **Reading caution:** The closing phrase about the mission's futility is compressed in the printed line and should be rechecked before publication as a verbatim quotation.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I030.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I030.ruled.01","volume":1,"page":30,"physical_pdf_page":43,"layer":"ruled","title":"Why fear has an obligatory force on the opponent's account","arabic":null,"arabic_anchors":"«(قوله خوف العقاب) يعني أن الخوف من العقاب على ترك معرفة الله ضرر ... فكانت واجبة».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “fear of punishment”: the feared punishment for abandoning recognition of God constitutes the apprehension of harm. Because obtaining knowledge removes that fear, the Muʿtazilite argument treats knowledge, and what is needed to obtain it, as obligatory. The note explains the **rational avoidance-of-harm inference**; it does not independently establish that this particular danger is actual.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I030.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I030.upper.01","volume":1,"page":30,"physical_pdf_page":43,"layer":"upper","title":"Positions concerning the source of obligation","arabic":null,"arabic_anchors":"«(وعند المعتزلة) النظر في معرفة الله تعالى واجب لكَوْنِه مقدمة للمعرفة الواجبة»؛ «(لكونها دافعة لضرر) مظنون وهو (خوف العقاب)»؛ «فالوجوب عندنا شرعي وعندهم عقلي».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"“According to the Muʿtazilites,” examination directed toward knowledge of God, exalted is He, is obligatory, since it is a prerequisite for the knowledge that is obligatory. That knowledge wards off a harm which is thought possible, namely **fear of punishment**. Thus for us the obligation is **legal/revelatory**, whereas for them it is **rational**. The parenthesized phrases belong to the quoted matn, while the explanatory connectives belong to the sharḥ.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I030.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I030.upper.02","volume":1,"page":30,"physical_pdf_page":43,"layer":"upper","title":"Their circularity objection against a revealed command to inquire","arabic":null,"arabic_anchors":"«(قالوا لو لم يجب) النظر (بالشرع لما صح)»؛ «(النظر في المعجزة)»؛ «وفي جميع ما يتوقف ثبوته على ثبوته»؛ «(قبل ثبوت الشرع)».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"They argue: if inquiry were not already obligatory before appeal to revelation, what would justify the demand that one investigate the Prophet's miracle and the other indications on which the establishment of revelation's authority depends? A command of religious law to perform the very inquiry by which the truth of that law is to be established cannot, without circularity, be the **first ground** of the inquiry's obligatoriness. More particularly, the Prophet, blessings and peace be upon him, directs a hearer to the miracle; the hearer might say that he is not obliged to investigate until the obligation has been established by the law, while the authority of that law depends on the examination of the miracle. The opponent thus attempts to derive a **rationally prior** obligation.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I030.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I031.lower.01","volume":1,"page":31,"physical_pdf_page":44,"layer":"lower","title":"The investigation/obligation regress and competing first duties","arabic":null,"arabic_anchors":"«(قوله ولا يثبت الشرع عندي ما لم أنظر الخ)»؛ «(قوله وثانياً الخ)»؛ «الجواب بأن عدم الإلزام ...»؛ «وجوب النظر في نفس الأمر»؛ «وجوب العلم»؛ «فأول الواجبات هو النظر والمعرفة لفظاً ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The gloss reconstructs the opponent's refusal to investigate: if the religious law cannot be established without an inquiry into its proofs, then telling him that he is legally obligated to inquire seems to presuppose what the inquiry is meant to establish. The marginal author replies that the threatened regress depends on conflating the **objective bindingness** of a duty with the person's **awareness of that bindingness**. If what is at issue is knowledge of the legal command, further examination may be needed before one knows it, but it does not follow that there is no duty in the order of things. The margin separately distinguishes rationally knowing that one must investigate, actually investigating, and acquiring the knowledge sought. Since these are not one and the same act, asking which is “first” without indicating the ordering relation produces a verbal dispute. Some schools make **knowledge** first as the end; others **investigation** first as the means; still others the **intention** to investigate, because a deliberate act involves a prior determination. **Reading caution:** The bottom line of the marginal text continues the debate; this paragraph is a connected first-pass reading, not a line-exhaustive verified transcription.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I031.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I031.ruled.01","volume":1,"page":31,"physical_pdf_page":44,"layer":"ruled","title":"What exactly depends on proving the law?","arabic":null,"arabic_anchors":"«(قوله بأن المتوقف على ثبوته الخ)»؛ «وفي نسخة بأن المتوقف على النظر ...»؛ «فلا يحتاج إلى تقدير الثبوت عند المكلف».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “what depends on its establishment”: a separate note refers to a **different printed wording** in another copy: “what depends on investigation.” On that reading, the sentence requires no supplementary insertion of “the law's establishment *for the legally responsible person*.” This is a reported reading, **not a manuscript variant verified in Stage 76**. The note should remain distinct from the principal commentary.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I031.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I031.upper.01","volume":1,"page":31,"physical_pdf_page":44,"layer":"upper","title":"Can someone refuse inquiry until inquiry has been proved obligatory?","arabic":null,"arabic_anchors":"«ولا يثبت الشرع عندي ما لم أنظر لأن ثبوته نظري»؛ «(ورد) أولا ...»؛ «لأن النظر وإن كان واجباً عقلاً لكن وجوبه ليس ضرورياً بل كان نظرياً»؛ «لا أنظر ما لم يجب ولا يجب ما لم أنظر».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The interlocutor says: “Religious law is not established for me until I investigate, for establishing its authority is itself a matter of inference.” The answer begins by challenging the alleged priority. Even if inquiry is deemed obligatory by reason, the **judgment that it is obligatory** need not be a primitive self-evident judgment; it can itself be established inferentially. The sceptical hearer could then say, even to the Muʿtazilite: “I shall not investigate until doing so is proved obligatory, and it cannot be proved obligatory until I investigate.” Merely moving the duty from revelation to reason does not automatically remove the threatened circle. The lower notes take up the force of this counter-objection.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I031.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I031.upper.02","volume":1,"page":31,"physical_pdf_page":44,"layer":"upper","title":"Does inquiry or knowledge come first among the obligations?","arabic":null,"arabic_anchors":"«(الشرع) عند المكلف»؛ «(هو العلم بالوجوب) أي وجوب النظر»؛ «(لا نفس الوجوب)»؛ «(ثم إنها) أي المعرفة (أول) الواجبات المقصودة»؛ «(والنظر فيها) ... (وسيلة إليها)»؛ «فإن أراد أول المعرفة ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The author distinguishes the **obligation itself** from **knowledge of the obligation**. A requirement can be binding without the agent's already having arrived at an explicit demonstration that it is binding; otherwise each needed act would presuppose a prior complete knowledge of its own duty. The inquiry then turns to the expression “the **first duty**”: some mean the first **object intended**, namely recognition of God; others mean the earliest **means to the object**, namely rational examination. Yet a third formulation says that the **first intention to investigate** precedes the actual investigation. The conclusion depends on whether “first” refers to priority **as an aim** or priority **in the process of bringing about the aim**. The last upper clauses continue into I:32.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I031.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I032.lower.01","volume":1,"page":32,"physical_pdf_page":45,"layer":"lower","title":"What rests on the prior establishment of duty?","arabic":null,"arabic_anchors":"«(قوله بل القصد الخ)»؛ «على ما لم يثبت الشرع ...»؛ «(قوله بل يلزم الدور الخ)»؛ «المعرفة بمعنى الجهل بالمطلوب»؛ «القدرة والإرادة»؛ «النظر في نفس الأمر».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The gloss returns to the concern that, if the authority of law has not been established, the attempt to derive an **obligation to investigate** from a legal command threatens circularity. But it is not necessary that **the agent know the duty's proof** before the duty be binding in itself. Some writers instead take the lack of prior knowledge of the **sought object** to be the motive for investigation: inquiry ordinarily begins with not yet knowing the conclusion, not with a demonstration of the very duty to inquire. The marginal writer distinguishes that epistemic condition from the **power and will** needed to undertake the inquiry. If one calls the earlier conditions “the first obligations,” a further specification of what “first” means is needed; otherwise a disputed logical ordering is merely restated as a practical command.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I032.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I032.lower.02","volume":1,"page":32,"physical_pdf_page":45,"layer":"lower","title":"Is transmitted certainty dependent on rational preliminaries?","arabic":null,"arabic_anchors":"«(قوله لأن يلزم الدور الخ)»؛ «ثبوت النقل من العلم بصدق الناقل المبني على ثبوت الصانع وبعثة النبي صلى الله عليه وسلم ودلالة المعجزة»؛ «بطريق إثباته في العقل دون ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"The argument concerning revelation is sharpened: certainty that a report is authoritative rests on knowledge that the reporter is truthful; in the prophetic case this includes the existence of the Creator, the sending of the Messenger, and the evidentiary significance of miracles. These are not established merely by repeating the report whose authority is under examination. Thus the **reliability of transmission**, as used in theological proof, presupposes some prior rational considerations. The note ends with a transition to the general philosophical topics opened on I:33. **Reading caution:** The final lower words run into a heavily crowded line; the summary here does not claim a complete diplomatic extraction or conclusive wording.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I032.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I032.ruled.01","volume":1,"page":32,"physical_pdf_page":45,"layer":"ruled","title":"The sense of a “prior intention”","arabic":null,"arabic_anchors":"«(قوله بل القصد الخ)»؛ «وربما يظهر للنفس ما يصير مبدأ باعثاً على القصد»؛ «القصد أعم ...».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"On “rather, the intention”: a preliminary apprehension can arise in the soul and become the motive that prompts intention. This should not be made into an infinite series of **deliberate intentions before every intention**; the earlier occurrence is not necessarily an act of intending in the same sense as the later one. The note therefore distinguishes a first prompting apprehension from the deliberate intention to proceed with rational inquiry.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"unassigned printed note/commentary","source_image":"source_images/I032.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I032.upper.01","volume":1,"page":32,"physical_pdf_page":45,"layer":"upper","title":"Differing accounts of the first obligation","arabic":null,"arabic_anchors":"«الواجبات مطلقاً وإلا فلا نزاع في أن أول الواجبات النظر لتوقف المعرفة عليه»؛ «(والدليل) هو ما يمكن أن يتوصل بالنظر فيه إلى حكم»؛ «(جازم أو غير جازم)»؛ «(وقد خص) بالحكم (الجازم في مقابلة الأمارة)».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"—[if one speaks of the first of] the obligations **without further qualification**; otherwise there is no disagreement that investigation precedes knowledge in the order of **the means required for obtaining it**. “Proof” is then defined as that by the consideration of which one may reach a judgment—whether a **decisive** or a **nondecisive** judgment, according to the broader usage. The expression “proof” is also employed more strictly for what brings about a **decisive judgment**, in contrast with an *amāra*—an indication that yields probability. The notes explain why the broader and narrower uses should not be silently collapsed.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I032.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I032.upper.02","volume":1,"page":32,"physical_pdf_page":45,"layer":"upper","title":"Rational proof and reliable report","arabic":null,"arabic_anchors":"«(على عقل) وسماع من الخبر الصادق»؛ «(والا) يتوقف شيء منه عليه»؛ «(عمومة القرآن القطع)»؛ «(ولازم بالحكم)»؛ «(لا يثبت إلا بالعقل)».","arabic_status":"selected_locating_anchors_not_diplomatic","english":"A proof is divided into **rational evidence** and evidence transmitted from **truthful report**. The text invokes the Qurʾān and transmitted reports and distinguishes the grounds on which their evidentiary force is established. An argument from report cannot simply bypass reason altogether: the conditions that make an utterance *reliable evidence* must themselves be known, while some of those conditions are established through rational investigation. Conversely, the fact that reason supplies indispensable premises does not erase the distinct evidentiary role of transmission. **Reading caution:** Several short connectors in the crowded upper printing need a second exact transcription; these English clauses preserve the argumentative order, not an independently certified Arabic critical text.","reading_status":"provisional_source_facing_not_line_exhaustive","attribution":"Taftazani matn within Sanandaji sharh","source_image":"source_images/I032.png","stage":76,"notes":["Source image examined, selected anchors checked where legible. Long Arabic gloss not fully transcribed. No independent second source proof."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I033.lower.01","volume":1,"page":33,"physical_pdf_page":46,"layer":"lower","title":"The possibility of demonstrations in this general science","arabic":null,"arabic_anchors":"«التعقل والتوقف الشيء على نفسه»؛ «لكن ينبغي أن يعلم أن ذلك إنما هو فيما يقصد منه حصول القطع»؛ «بمجرد إفادة الظن»؛ «التواتر نظرياً واستدلالياً»؛ «(قوله من الواجب والجوهر والعرض الخ)».","arabic_status":"selected_locating_anchors_not_full_transcription","english":"The margin returns to a methodological warning: if the act of arriving at knowledge required, as a necessary prior condition, the very knowledge to be acquired, the inquiry would be circular. But the objection must be qualified by the **epistemic aim** of a proof. An argument intended to produce certainty is not the same as an indication that yields only probability. Some scholars regard the cognition established by recurring reports or testimony as depending on intellectual attention to particular conditions, while others take its force more immediately. The writer cautions against using the uncertainty of a particular example to reject the whole field of demonstrations. In the ensuing discussion of existents, the categories “Necessary,” “substance” and “accident” serve as a survey of what can be considered; they do not imply that every shared predicate is an independently existing universal.","source_image":"images/I033.png","reading_status":"provisional_source_facing_not_clause_exhaustive","attribution":"unassigned printed commentary","stage":75,"notes":["Printed page examined manually; marginal English remains partly interpretative; no independent second proof; not a complete page."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I033.ruled.01","volume":1,"page":33,"physical_pdf_page":46,"layer":"ruled","title":"Why these matters precede the special inquiries","arabic":null,"arabic_anchors":"«(قال رحمه الله الباب الثاني في الأمور العامة)»؛ «لما أن فيما يختص بواحد من الواجب والجوهر والعرض ما يحتاج إلى باب معرفة الأحوال المشتركة»؛ «الوجود والعلية أو بين الاثنين».","arabic_status":"selected_locating_anchors_not_full_transcription","english":"On the author's heading “General Matters”: the reason for examining them here is that the discussions specific to the Necessary, substances or accidents depend upon an earlier investigation of concepts common among different kinds of existent. Existence and causality are obvious examples, while other concepts apply to two of those kinds or concern the contrast between them. The note is a justification of **the sequence of inquiry**, not another independent proof of the particular theses to follow.","source_image":"images/I033.png","reading_status":"provisional_source_facing_not_clause_exhaustive","attribution":"unassigned printed commentary","stage":75,"notes":["Printed page examined manually; marginal English remains partly interpretative; no independent second proof; not a complete page."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I033.upper.01","volume":1,"page":33,"physical_pdf_page":46,"layer":"upper","title":"Transition from logic to general metaphysics","arabic":null,"arabic_anchors":"«العقائد وإثبات مباحث أخرى تتوقف عليها العقائد فهذا أوان الشروع في المقاصد فنقول»؛ «(الباب الثاني في الأمور العامة)».","arabic_status":"selected_locating_anchors_not_full_transcription","english":"The discussion has established [the preliminary instruments for examining] articles of belief and other matters upon which such articles depend. It is now time to turn to the principal objectives. The text therefore announces **Book Two: General Matters** (*al-umūr al-ʿāmma*), that is, questions which recur in the investigation of existence and do not belong exclusively to one special kind of thing.","source_image":"images/I033.png","reading_status":"provisional_source_facing_not_clause_exhaustive","attribution":"mixed Taftazani lemma and Sanandaji sharh","stage":75,"notes":["Printed page examined manually; marginal English remains partly interpretative; no independent second proof; not a complete page."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I033.upper.02","volume":1,"page":33,"physical_pdf_page":46,"layer":"upper","title":"The scope and divisions of *al-umūr al-ʿāmma*","arabic":null,"arabic_anchors":"«الشاملة للموجودات بأسرها من الواجب والجوهر والعرض كالوجود والوحدة»؛ «فإن كل موجود وإن كان كثيراً له وحدة ما باعتبار»؛ «وكثرة الموجودات»؛ «كالإمكان الخاص والحدوث والوجوب بالقيد والكسرة والعلية والمعلولية»؛ «(تصور الوجود)».","arabic_status":"selected_locating_anchors_not_full_transcription","english":"These general matters include those applicable across what exists—Necessary Being, substance and accident—such as **existence and unity**. Even a many-sided existent has some unity under an appropriate consideration. Other general matters include plurality, possibility in the restricted sense, origination, necessity, and the relationships of cause and effect, though some do not belong to all existents in precisely the same manner. The discussion follows an established pedagogical order and begins with the **conception of existence** (*taṣawwur al-wujūd*). [The main paragraph continues on I:34.]","source_image":"images/I033.png","reading_status":"provisional_source_facing_not_clause_exhaustive","attribution":"mixed Taftazani lemma and Sanandaji sharh","stage":75,"notes":["Printed page examined manually; marginal English remains partly interpretative; no independent second proof; not a complete page."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I034.lower.01","volume":1,"page":34,"physical_pdf_page":47,"layer":"lower","title":"The scope of general notions","arabic":null,"arabic_anchors":"«لا يشمل الموجود أصلاً كالامتناع»؛ «وما يخص الواجب كالقدم والوجوب»؛ «وما يخص الممكن في مقابلة الإمكان»؛ «أما العدم فكذلك عند المتكلمين»؛ «(قوله إنه يتوقف على تصور الوجود الخ)».","arabic_status":"selected_locating_anchors_not_full_transcription","english":"The gloss first considers what qualifies as a **general matter**. Not everything discussed under this heading applies positively to every actual existent; for example, impossibility is a concept concerning what is not actual, while eternity and certain kinds of necessity are specific to the Necessary, and contingency pertains to possible beings. Nonexistence too is a general contrast, but it is not an existent thing of the same order. Philosophers and theologians differ in how they classify such topics. Thus “general” concerns the scope and utility of the inquiry, not the claim that all its subjects are actual substances. On the evidence from the self-evident judgement, the gloss asks whether one means immediate conception or merely a certain affirmation once the terms have been understood.","source_image":"images/I034.png","reading_status":"provisional_source_facing_not_clause_exhaustive","attribution":"unassigned printed commentary","stage":75,"notes":["Printed page examined manually; marginal English remains partly interpretative; no independent second proof; not a complete page."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false},{"id":"I034.lower.02","volume":1,"page":34,"physical_pdf_page":47,"layer":"lower","title":"The logical difference between *badāha* and *muṣādara*","arabic":null,"arabic_anchors":"«بديهة تصور الموجود بالضرورة»؛ «(قوله فصادرة)»؛ «إن أراد بديهة الحكم»؛ «بداهة جميع أجزائه»؛ «العلم بالمركب»؛ «جميع أجزائه».","arabic_status":"selected_locating_anchors_not_full_transcription","english":"A judgement may be self-evident *once its terms are understood*, while understanding those terms can require earlier attention. The objection therefore rejects an **equivocation** between an evident proposition and an evident conception. If the original argument assumes that the constituent notions are already self-evident, it has assumed what it seeks to prove; if it means only that the combination yields an immediate assent, the proof is insufficient. The marginal author also asks about the difference between grasping the **whole proposition** and grasping each of its **parts**, and why certainty of the former should be thought to entail separate certainty concerning each part. The beginning of the next page continues this line of criticism.","source_image":"images/I034.png","reading_status":"provisional_source_facing_not_clause_exhaustive","attribution":"unassigned printed commentary","stage":75,"notes":["Printed page examined manually; marginal English remains partly interpretative; no independent second proof; not a complete page."],"source_kind":"locating_arabic_anchors_only","all_printed_clauses_literally_translated":false,"independent_second_proof":false,"textual_witness_collation":false}]);